window.EXECUTION_MATERIAL=(window.EXECUTION_MATERIAL||[]).concat([{"kind":"text","text":"مقرر التنفيذ الجبري"},{"kind":"text","text":"مقرر المادة"},{"kind":"text","text":"المادة العلمية"},{"kind":"text","text":"القراءات الأساسية والمساندة"},{"kind":"text","text":"الموضوعات والإجراءات والتطبيقات"},{"kind":"text","text":"مسار تعليمي عن بعد"},{"kind":"text","text":"بسم الله الرحمن الرحيم"},{"kind":"heading","text":"مقدمة"},{"kind":"text","text":"التنفيذ الاختياري هو منطق القانون"},{"kind":"text","text":"1- لا شك أن المعاملات القانونية التي تحدث كل يوم بين أفراد المجتمع لا تقع تحت حصر. ولا شك أيضا أن المدينين يقومون بالوفاء بالتزاماتهم في الأعم الأغلب من هذه المعاملات، دون أن تثور ثمة مشكلة. فشعور الأفراد بوجود تنظيم قانوني يضمن الإجبار على تنفيذ الالتزام عند اللزوم، فضلا عن الوازع الديني أو الأخلاقي، يجعل معظمهم يقوم بالوفاء طواعية، أي يقوم بالتنفيذ الاختياري لالتزاماته. ويجب أن تكون نتائج قياس الأثر التشريعي متوافقة مع هذا التصور، وإلا توجب على واضع السياسة التشريعية إدخال التعديلات اللازمة."},{"kind":"text","text":"اللجوء إلى القضاء هو أيضا منطق القانون"},{"kind":"text","text":"2- لم يغب عن ذهن المشرع أن هناك من الأشخاص من لا يوف بالتزامه تلقائيا. وكان لابد للنظام القانوني أن يواجه هذا الاستثناء، بأن يمكن للدائن من الحصول على حماية القضاء، من خلال إعطائه الحق في رفع دعوى قضائية للحصول على حكم يلزم المدين بالوفاء. صدور هذا الحكم القضائي يدفع كثيرا من المدينين إلى الوفاء بالفعل، وقد تأكد لهم أنهم في نظر القانون ملتزمون لا محالة. على أن هذا الوفاء من جانبهم يعتبر رغم ذلك تنفيذا اختياريا، طالما قام به المحكوم عليه بإرادته ودون تدخل خارجي."},{"kind":"text","text":"لا ينفع تكلم بحق لا نفاذ له"},{"kind":"text","text":"3- ليس بمستغرب في أحايين كثيرة أن يظل المدين ممتنعا عن الوفاء رغم صدور حكم قضائي يلزمه بذلك. وليس بمستغرب أيضا أن يظل الدائن رغم ذلك ممنوعا من اقتضاء حقه بنفسه. فهو ممنوع من استعمال القوة بنفسه للحصول على حقه، ولو كان حقه هذا ثابتا في حكم، وإلا اضطرب الأمن والنظام في المجتمع."},{"kind":"text","text":"ولأنه \"لا ينفع تكلم بحق لا نفاذ له\"، كان لابد أن يتضمن النظام القانوني ما يكفل حصول الدائن على حقه جبرا، ومن خلال قوة الدولة نفسها، وليس من خلال قوته الذاتية، والتي تظل ممنوعة. هذا الحصول الجبري للحق يتمثل إما في الضغط على إرادة المدين لإجباره على تنفيذ التزامه من خلال الوفاء، وهو ما يجعل التنفيذ رغم ذلك اختياريا، وإلا فمن خلال التنفيذ الجبري بمعنى الكلمة. هذا الأخير هو ما ستظهر فيه الدولة، ممثلة في سلطة التنفيذ، وفي إخضاع المدين لإجراءات تنزع منه أمواله نزعا. سلطة التنفيذ هذه- وكما سنرى بعد قليل- تتمثل في قاضي التنفيذ ومعاونيه. من هنا كان التنفيذ الجبري هو مناسبة للجوء ثانية إلى القضاء."},{"kind":"text","text":"الحاجة إلى قانون للتنفيذ الجبري"},{"kind":"text","text":"4- التنفيذ الجبري هو إذا استعمال القوة الجبرية بواسطة سلطة التنفيذ في الدولة، بأن يتحول التزام المدين إلى واقع ملموس، بأن يحصل الدائن- رغما عن المدين- على حقه بالفعل. ومن أبرز صور هذا التنفيذ هو الحجز على أموال المدين وبيعها جبرا وإعطاء الدائن حقه من ثمن البيع."},{"kind":"text","text":"ولا شك أن اللجوء إلى الإجبار لتمكين الدائن من الحصول على حقه بالفعل يحتاج إلى تنظيم قانوني محكم، وهو ما نطلق عليه \"قانون التنفيذ الجبري\". ذلك لأن هذا الإجبار ينطوي على مساس بأموال المدين- إذ كثيرا ما ينتهي إلى نزع ملكية هذه الأموال- فضلا عن المساس بسمعته."},{"kind":"text","text":"نتائج الإجبار الشديدة هذه تحتاج ولا شك إلى قواعد قانونية تضمن عدم الخضوع للتنفيذ الجبري إلا بعد التأكد من ثبوت حق الدائن فيه. لذلك يجب ابتداء بيان وتنظيم المصدر المنشأ لهذا الحق، والذي لا يجوز التنفيذ الجبري إلا به، والمسمى بالسندات التنفيذية."},{"kind":"text","text":"هناك أيضا حاجة إلى قواعد قانونية تضع تنظيما مسبقا لمحل التنفيذ، أي المال الذي يمكن أن يرد عليه التنفيذ. فهناك على الأقل حاجة إلى بيان الأموال التي لا يجوز التنفيذ عليها خاصة بطريق الحجز. هذه القواعد يجب أيضا أن تستبعد شخص المدين من أن يكون محلا للتنفيذ."},{"kind":"text","text":"ولكي يكتمل البناء القانوني لأركان التنفيذ يجب أيضا إيجاد القواعد القانونية اللازمة لتنظيم سلطة التنفيذ التي تتولى الإشراف عليه."},{"kind":"text","text":"ولن تقف الحاجة إلى تنظيم قانوني للتنفيذ عند هذا الحد. إذ يجب أن يقفز إلى سطح الذهن فورا ضرورة وجود تنظيم قانوني لعملية التنفيذ ذاتها، أي العملية الإجرائية التي يجب أن تكون مرسومة مقدما، وكذلك ما يجب أن يسبقها من إجراءات تمهيدية، وأيضا ما يعقبها من توزيع لحصيلة التنفيذ."},{"kind":"text","text":"ولا تزال الحاجة إلى التنظيم القانوني للتنفيذ الجبري مستمرة. إذ يجب بالتوازي مع كل ما سبق، تنظيم وسائل احتياطية للإجبار- إن جاز التعبير- بطريق غير مباشر، على التنفيذ الاختياري. والمقصود بذلك وسائل للتأثير على إرادة المدين وحثه على التنفيذ، والذي يظل رغم ذلك اختياريا. وتزداد أهمية هذه الوسائل في كونها تخفف العبء أيضا على سلطة التنفيذ الجبري. من هنا كانت ضرورة تنظيم وسائل مثل حبس المدين أو منعه من السفر أو الغرامة التهديدية."},{"kind":"text","text":"وأخيرا يجب تنظيم التقاضي بشأن المنازعات التي تثور أثناء التنفيذ وبمناسبته."},{"kind":"text","text":"وإذا كان لكل قانون غاية تسعى الصياغة القانونية لقواعده إلى تحقيقها، فإن غاية قانون التنفيذ الجبري هي الانحياز لصالح الدائن صاحب الحق في التنفيذ، بتمكينه من أن يقهر عناد المدين الممتنع عن الوفاء بالتزامه رغم ثبوته في سند يؤكد وجوده، من خلال إجراءات مبسطة لا تشكل خصومة. على أن إعلاء قيمة هذه الغاية لا يجب أن يحجب عن واضعي النصوص غاية أخرى تجب أيضا مراعاتها، وهي مراعاة الجانب الإنساني للمدين. فإذا كان ولابد من أن ينال التنفيذ منه، فمن أمواله وليس من شخصه، ومع ضمان احتفاظه بالحد المعقول من الكرامة الإنسانية."},{"kind":"text","text":"وهكذا يتواجد قانون للتنفيذ الجبري من جماع ما تقدم. فهو إذا مجموعة القواعد القانونية التي تنظم الاقتضاء الجبري للحقوق بواسطة سلطة التنفيذ في الدولة."},{"kind":"text","text":"وكل الموضوعات السابقة التي تنشغل بتنظيمها قواعد التنفيذ الجبري الواردة في الكتاب الثالث من قانون الإجراءات المدنية (المواد من 206 إلى 327)، هي في الوقت ذاته محور هذه الدراسة."},{"kind":"heading","text":"خطة الدراسة"},{"kind":"text","text":"5- سوف تتوزع موضوعات الدراسة على أبواب أربعة، بحيث يخصص الباب الأول لأركان التنفيذ الجبري، بينما ينشغل الثاني بطرق هذا التنفيذ، وتحديدا التنفيذ بطريق الحجز. أما الباب الثالث فيتناول وسائل الإجبار غير المباشر على التنفيذ الاختياري، بينما الرابع والأخير سيكون عن منازعات التنفيذ."},{"kind":"heading","text":"الباب الأول: أركان التنفيذ"},{"kind":"heading","text":"تقسيم:"},{"kind":"text","text":"6- أركان التنفيذ هي العناصر الضرورية التي لا يتصور قيام عملية تنفيذ جبري بدونها. فهناك أولا المصدر المنشئ للحق في التنفيذ الجبري وهو السند التنفيذي، فهو ركن التنفيذ الأعظم. هذا السند لا يوضع موضع التنفيذ تلقائيا، وإنما لابد من التقدم بطلب استعماله بواسطة صاحب الحق في ذلك، والمسمى بطالب التنفيذ، في مواجهة شخص آخر، يسمى بالمنفذ ضده. والذي يشرف على عملية التنفيذ قاض يسمى بقاضي التنفيذ، ويعاونه في إجرائه موظف عام أو في حكمه يسمى بالقائم بالتنفيذ. هناك إذا عدة أشخاص لا غنى عنهم في أي معاملة تنفيذية، وهم يشكلون الركن الثاني من أركان التنفيذ. وأخيرا هناك محل التنفيذ، وهو غالبا المال الذي تنصب عليه إجراءات التنفيذ، وهو الركن الثالث من أركان التنفيذ."},{"kind":"text","text":"ولذلك سوف تنقسم الدراسة في هذا الباب إلى فصول ثلاثة، بحيث يخصص الفصل الأول لسبب التنفيذ، أي لركن التنفيذ الأول وهو السند التنفيذي، بينما يخصص الفصل الثاني لأشخاص التنفيذ مع دراسة خاصة لأهمهم وهو قاضي التنفيذ، أما الفصل الثالث فعنوانه هو محل التنفيذ."},{"kind":"heading","text":"الفصل الأول: السند التنفيذي"},{"kind":"heading","text":"مقدمة"},{"kind":"text","text":"السند التنفيذي مفترض ضروري وكاف للتنفيذ الجبري"},{"kind":"text","text":"7- \"لا يجوز التنفيذ الجبري إلا بسند تنفيذي..\" (مادة 1- 212). هذه القاعدة تعبر عن ركن ركين من أركان التنفيذ الجبري، حيث يمتنع تماما البدء فيه أو حتى اتخاذ مقدماته، إلا بعد حيازة الدائن لأحد السندات التنفيذية. والسند التنفيذي هو عمل قانوني توافرت فيه شروط معينة- موضوعية وشكلية- نص المشرع على أنه وحده الجدير بأن يعطي صاحبه الحق في طلب الحماية التنفيذية."},{"kind":"text","text":"فقد اصطفى المشرع بعضا من الكتابات، المثبتة للحقوق على نحو مؤكد، واعتبرها الجديرة دون غيرها لتكون سببا للتنفيذ، أي مصدرا للحق في التنفيذ الجبري، ولذلك أسماها بالسندات التنفيذية. فلا يكفي لتحريك سلطة التنفيذ أن يكون حق طالب التنفيذ ثابتا بأية وسيلة، وإنما ثابتا في سند، أي مكتوبا، وأن يكون التشريع قد أعطى هذا السند المكتوب صفة السند التنفيذي. فالسندات التنفيذية هي فقط تلك التي ورد بها نص في التشريع، وبالتالي لا تجوز الإضافة إليها عن طريق الاجتهاد أو القياس، كما لا يجوز للإرادة المشتركة للأفراد الاتفاق على زيادتها أو الانتقاص منها."},{"kind":"text","text":"على أن المتأمل في هذه السندات سيجدها في معظمها- وليس جميعها - سندات رسمية. على أنه يستوي بعد ذلك أن تكون الكتابة عليها ورقية أو الكترونية."},{"kind":"text","text":"وهكذا يتبين أنه عند توافر السند التنفيذي بالمعنى السابق، سوف يضاف إلى الحق الموضوعي الثابت فيه حق آخر هو \"الحق في التنفيذ الجبري\"، بحيث يكون الثابت اسمه في السند ليس فقط صاحب حق موضوعي، وإنما أيضا صاحب حق في التنفيذ الجبري لاقتضاء حقه الأول، وبحيث لا يجوز لسلطة التنفيذ أن تمتنع عن إعمال مقتضاه. وبعبارة أخرى، فإنه إذا كان للحقوق الموضوعية مصادر متعددة كالعقد والفعل الضار وغيرهما، فإن الحق في التنفيذ الجبري له مصدر وحيد هو السند التنفيذي. هذا السند التنفيذي ذاته يتضمن بالضرورة حقا من الحقوق الموضوعية المتولدة من أحد مصادرها."},{"kind":"text","text":"سوف نتناول السندات التنفيذية من خلال عدة مباحث يخصص كل مبحث منها لدراسة كل سند بالتفصيل. وهي على الترتيب: الحكم القضائي، والأمر القضائي، ومحاضر الصلح التي تصدق عليها المحاكم، وحكم المحكم المصدق عليه، والمحرر الموثق، والسندات الأخرى التي أعطاها القانون هذه الصفة. ثم يخصص المبحث السابع لدراسة الشروط الموضوعية، والثامن للشروط الشكلية، وكلها شروط مطلوبة لاستعمال السند التنفيذي."},{"kind":"heading","text":"المبحث الأول: الحكم القضائي"},{"kind":"text","text":"تقسيم"},{"kind":"text","text":"8- لا شك في أن الحكم القضائي هو أهم السندات التنفيذية وأكثرها شيوعا من الناحية العملية. ولذلك يجب أن تحظى دراسته بأكبر قدر من التفصيل."},{"kind":"text","text":"وبادئ ذي بدء، ليس كل حكم قضائي يعتبر سندا تنفيذيا. فهناك شروط معينة يجب توافرها فيه لكي يكتسب هذا الوصف. ولذلك يجب أن تبدأ الدراسة في مطلب أول من هذا المبحث بالتعرف تفصيلا على الشروط الواجب توافرها في الحكم القضائي لكي يكون سندا تنفيذيا."},{"kind":"text","text":"وسوف يظهر أثناء دراسة هذه الشروط تعبير الحكم المشمول بالنفاذ المعجل، وهو تعبير خاص بالحكم الابتدائي عندما يكون سندا تنفيذيا. وهذا موضوع يستحق أن يحظى بدراسة تفصيلية في مطلب ثان."},{"kind":"text","text":"من الواضح إذا أن القوة التنفيذية للحكم تتأثر بوصفه. ولذلك يجب أن يتضمن التشريع نظاما إجرائيا لتصحيح ما قد يحدث من أخطاء في وصف الحكم. والمطلب الثالث من هذا المبحث سوف يتناول التظلم من وصف الحكم أو ما يسمى بالاستئناف الوصفي."},{"kind":"text","text":"وسوف يتبين لنا من الدراسة أن الحكم القضائي يمكن أن يكون سندا تنفيذيا رغم قابليته للإلغاء من خلال طرق الطعن. ومعنى ذلك أن التنفيذ الذي سيكون مبنيا على هذا الحكم سيكون قابلا هو الآخر للإلغاء. وإلغاء التنفيذ يعني ضرورة إعادة الحال إلى ما كان عليه. وقد يكون ذلك مستحيلا أو مرهقا. ولتوقي هذه المخاطر نشأت الحاجة إلى نظام لوقف تنفيذ الحكم بمناسبة الطعن فيه. ولذلك سوف يخصص المطلب الرابع لدراسة نظام وقف التنفيذ بمناسبة الطعن في الحكم."},{"kind":"heading","text":"المطلب الأول: الشروط الواجب توافرها في الحكم القضائي كسند تنفيذي"},{"kind":"text","text":"9- الحكم القضائي هو كل قرار تصدره محكمة مشكلة تشكيلا صحيحا، في نزاع- أو في مسألة متفرعة عنه- رفع إليها من خلال خصومة قضائية."},{"kind":"text","text":"ومن الطبيعي أن يكون الحكم القضائي بالمعنى الفني الدقيق- والضيق- هو أول السندات التنفيذية التي تذكرها المادة 212 والتي عددت السندات التنفيذية. ذلك لأنه إذا كان ممكنا الاستغناء عن معظم السندات التنفيذية، إلا أنه لا يمكن أبدا الاستغناء عنه. فحيازته لحجية الأمر المقضي فيه، تجعل الثقة في الحق الثابت به كبيرة لا تضاهيه في ذلك السندات التنفيذية الأخرى، وبالتالي يبدو مبررا اعتباره المصدر الأول للحق في التنفيذ الجبري."},{"kind":"text","text":"ولكن ليس معنى ذلك أن يتمتع كل حكم قضائي بالقوة التنفيذية. فهناك من الأحكام القضائية ما ليس بحاجة إلى تنفيذ، كما هي حالة الحكم غير الصادر في الموضوع أو غير الصادر بإلزام. فمثل هذا الحكم أو ذاك لا تنشغل به أصلا النظرية العامة للسندات التنفيذية."},{"kind":"text","text":"وهناك من الأحكام ما يحتاج إلى تنفيذ وتنشغل به هذه النظرية، إلا أن النصوص تتطلب لاعتباره سندا تنفيذيا شرطا إضافيا، هو بلوغه درجة معينة من الاستقرار، أو توافر أسباب أخرى تجعله جديرا بالتنفيذ ولو لم يبلغ هذه الدرجة بعد."},{"kind":"text","text":"فالمستفاد إذا من النظرية العامة للتنفيذ الجبري، ومن النصوص، أن شروطا ثلاثة يجب توافرها في الحكم القضائي من حيث المبدأ حتى يكون سندا تنفيذيا. هذه الشروط هي: أن يكون الحكم صادرا في الموضوع، وأن يكون الحكم صادرا بإلزام، وأن يكون الحكم نهائيا أو مشمولا بالنفاذ المعجل."},{"kind":"text","text":"الفرع الأول: الشرط الأول - أن يكون الحكم صادرا في الموضوع"},{"kind":"text","text":"10- للأحكام القضائية تقسيمات متعددة، منها التقسيم الذي ينطلق من المسألة التي فصل فيها الحكم. فوفقا لهذا المعيار، تنقسم الأحكام القضائية إلى أحكام فاصلة في الموضوع وأحكام صادرة دون الفصل في الموضوع. ومن أهم الآثار المترتبة على هذا التقسيم أن الأحكام الأولي هي فقط التي يمكن أن تكون سندات تنفيذية، بينما الثانية لا يمكن أن تكون كذلك."},{"kind":"text","text":"ويقصد بالحكم الصادر في الموضوع الحكم الذي يفصل في موضوع الدعوى، سواء بالكامل أم حتى في جزء منه. ينطبق ذلك مثلا على الحكم الصادر بالتعويض أو النفقة أو الأجر. يستوي بعد ذلك أن تكون الدعوى التي فصل الحكم في موضوعها هي دعوى موضوعية أم دعوى مستعجلة."},{"kind":"text","text":"والسبب الذي يجعل الحكم الصادر في الموضوع سندا تنفيذيا دون غيره من الأحكام، هو أنه وحده الذي من المحتمل أن يكون صادرا بإلزام- وهو المعنى الذي سوف نتعرف عليه لاحقا- وعندئذ لا يمكن الاستفادة منه إلا بعد قيام المحكوم عليه بأداء ما قضى به الحكم في الموضوع إما طوعا وإلا جبرا. بينما الأحكام التي لا تصدر في الموضوع لا تصدر أبدا بإلزام."},{"kind":"text","text":"فالحكم الفاصل في غير الموضوع هو الحكم الذي يفصل في مسألة إجرائية من مسائل الخصومة أو قبول الدعوى أو الإثبات. ينطبق ذلك مثلا على الحكم الصادر بعدم الاختصاص أو بعدم القبول أو الصادر بندب خبير. مثل هذا الحكم أو ذاك تتحقق الغاية منه بمجرد النطق به، دون الحاجة إلى اتخاذ أي إجراء من جانب المحكوم عليه أو من جانب سلطة التنفيذ، ولذلك لا تنشغل به نظرية السند التنفيذي، ولا يستلزم كذلك توافر الشروط الأخرى المطلوبة في الحكم القضائي كسند تنفيذي."},{"kind":"text","text":"11- ويلاحظ أننا في كل ما سبق نفترض أن الحكم الصادر في الموضوع هو حكم مدني. ويقصد بذلك الحكم الصادر في خصومة مدنية أي خصومة نشأت عن رفع دعوى غير جزائية. أما الحكم الجزائي فإن تنفيذه يخضع لنظام خاص. على أن من الأحكام الجزائية ما يخضع للتنفيذ القضائي المدني ويعتبر من السندات التنفيذية التي تنفذ مثل الأحكام المدنية. نقصد بذلك تحديدا \" الأحكام الجزائية فيما تضمنته من رد وتعويضات وغرامات وغيرها من الحقوق المدنية\" (مادة 2- 212 -أ إجراءات مدنية)."},{"kind":"text","text":"فالحكم بالرد لم يشرع للعقاب والزجر وإنما قصد به إعادة الحال إلى ما كانت عليه قبل ارتكاب الجريمة. فالرد وإن تضمن في ظاهره معنى العقوبة- بالنظر إلى أنه صادر بحكم جزائي على الجاني الذي ارتكب جريمة- إلا أنها عقوبة تتعلق بالحقوق المالية للمجني عليه. الرد إذا بمثابة تعويض مدني يحكم به القاضي الجزائي للمجني عليه عن ماله الذي استولى عليه الجاني دون حاجة إلى دخوله مدعيا بحق مدني."},{"kind":"text","text":"الفرع الثاني: الشرط الثاني- أن يكون الحكم صادرا بإلزام"},{"kind":"text","text":"12- من تقسيمات الأحكام القضائية أيضا- وتحديدا الأحكام الصادرة في الموضوع- التقسيم الذي ينطلق من آلية الاستفادة من مضمون الحكم. فوفقا لهذا التقسيم، تتنوع الأحكام القضائية إلى أحكام مقررة ومنشئة وصادرة بإلزام. والحكم القضائي لا يشكل في ذاته سندا تنفيذيا إلا إذا كان من هذا النوع الأخير."},{"kind":"text","text":"فالحكم الصادر بإلزام هو الحكم القاضي بإلزام المحكوم عليه بأداء معين. ينطبق ذلك مثلا على الحكم الصادر بدفع مبلغ من النقود- كما لو كان دين تعويض أو أجرا أو ثمنا أو نفقة- أو الصادر بتسليم البضاعة أو الصغير، أو بتسليم الأموال إلى الحارس المعين. يستوي بعد ذلك ان يكون الأداء الصادر به الحكم واردا في المنطوق أو في الأسباب المكملة له، كما يستوي أن يكون الحق محل الأداء حقا موضوعيا أو حتى حماية وقتية، كالنفقة الوقتية مثلا."},{"kind":"text","text":"فلأنه بدون التنفيذ الجبري- أو الطوعي- لهذا الأداء لا يمكن للمحكوم له الاستفادة من الحكم، كان منطقيا أن تكون هذه الخصيصة مفترضا ضروريا للحديث عن الحكم كسند تنفيذي."},{"kind":"text","text":"13- لا ينطبق ما سبق على الحكم المقرر. فالحكم التقريري هو الحكم الذي يقرر وجود الحق أو المركز القانوني أو ينفي وجوده دون أن يتضمن إلزام المحكوم عليه بأي أداء. فمن أمثلة الحكم التقريري الحكم الصادر ببراءة الذمة، أو بثبوت الملكية أو نفيها، أو بصحة العقد أو بطلانه أو بصحة التوقيع أو بالتزوير، أو بثبوت النسب أو نفيه، أو بإثبات الطلاق.."},{"kind":"text","text":"فلأنه يمكن للمحكوم له الاستفادة مما قرره الحكم التقريري لمجرد صدوره، ودون الحاجة إلى قيام المحكوم عليه بأي أداء، كان منطقيا ألا تنشغل نظرية السند التنفيذي بهذا الحكم."},{"kind":"text","text":"14- نصل الآن إلى الحكم المنشئ، وهو الحكم الذي ينشأ مركزا قانونيا لم يكن موجودا قبل صدوره، أو ينهي مركزا قانونيا أو يعدله. ينطبق ذلك مثلا على الحكم الصادر بالتطليق أو بشهر الإفلاس، أو بالفسخ أو بحل الشركة، أو بتعيين حارس قضائي أو بعزله، أو بتعديل التزام تعاقدي."},{"kind":"text","text":"هذا الحكم أيضا يحقق مقصوده لمجرد النطق به، ويستفيد منه المحكوم له دون الحاجة إلى تدخل من جانب المحكوم عليه، وبالتالي دون حاجة إلى تدخل سلطة التنفيذ. ولذلك لا يوجد مبرر لكي تنشغل به النظرية العامة للسندات التنفيذية. ولذلك أيضا فإن هذا الحكم يرتب أثره المنشئ ولو لم تتوافر فيه باقي الشروط المطلوبة في الحكم القضائي الذي يعد سندا تنفيذيا."},{"kind":"text","text":"15- ويلاحظ أخيرا أنه كثيرا ما نجد أن الحكم القضائي الواحد الصادر بإلزام ينطوي في حقيقته على شقين أحدهما تقريري أو إنشائي والآخر بإلزام. مثال ذلك أن يقرر الحكم ثبوت المسؤولية ويلزم بدفع مبلغ معين كتعويض، أو يحكم بالفسخ ويلزم بإعادة الحال إلى ما كان عليه. في مثل هذه الأحوال لن يكون الحكم بجميع منطوقه سندا تنفيذيا وإنما فقط شق المنطوق الذي قضى بإلزام، وهو أداء التعويض في المثال الأول وإعادة الحال في المثال الثاني."},{"kind":"heading","text":"16- ضرورة التفرقة بين كون الحكم \"ملزما\" وكونه صادرا \"بإلزام\"، أو التفرقة بين \"نفاذ\" الحكم و\"تنفيذه\":"},{"kind":"text","text":"يجب التمييز بين مصطلح \"الحكم الصادر بإلزام\" والذي تهتم به النظرية العامة في التنفيذ الجبري، وبين ما قد يختلط به من عبارات، وخاصة عبارة أن كل حكم قضائي يعتبر حكما \"ملزما\". فالمقصود بهذه العبارة الأخيرة أن أي حكم قضائي يعتبر مرتبا لمنطوقه على سبيل الحتم، أي دون أن يكون ذلك متوقفا على إرادة المحكوم عليه أو حتى إرادة المحكوم له. ويعبر عن ذلك أيضا \"بنفاذ\" الحكم. فعندما يعلن الحكم رفض الدعوى أو حتى القضاء لصاحبها بما يدعيه، كما لو قرر صحة العقد أو بطلانه أو ثبوت المسؤولية أو غير ذلك، فإن هذا الأثر أو ذاك يترتب فور النطق بالحكم لكونه ملزما، ولأن نفاذه يعتبر أثرا مباشرا من آثار النطق به. يستوي في كل ما سبق أن يكون الحكم صادرا في الموضوع أو صادرا دون الفصل فيه، وقابلا للطعن فيه أو غير قابل لذلك، وقطعيا أو غير قطعي."},{"kind":"text","text":"على أن هناك طائفة من الأحكام- الصادرة في الموضوع تحديدا- تسمى بالأحكام الصادرة \"بإلزام\"، وهي أحكام لا يمكنها أن ترتب أحد آثارها- وهو الأثر التنفيذي- لمجرد النطق بها، وإنما هي تنتظر قيام المحكوم عليه بأداء معين. فإذا لم يقم بذلك، صار ترتيب الحكم لهذا الأثر في حاجة إلى ضرورة قيام سلطة التنفيذ بإجباره على التنفيذ. وعندئذ سيكون مطلوبا استيفاء هذا الحكم الصادر بإلزام لشروط معينة يفرضها النظام القانوني للتنفيذ الجبري ولا يفرضها على الحكم الذي لا يصدر بإلزام. مفاد ما سبق إذا أن حكم الإلزام هذا هو الذي يمكن اعتباره سندا تنفيذيا، والذي تنشغل به نظرية التنفيذ الجبري."},{"kind":"text","text":"الفرع الثالث: الشرط الثالث- أن يكون الحكم نهائيا أو مشمولا بالنفاذ المعجل"},{"kind":"text","text":"17- قد يكون الحكم القضائي بطبيعته مما يحتاج إلى تنفيذ، بأن يكون صادرا بإلزام وفي الموضوع. ومع ذلك لن يعتبره القانون سندا تنفيذيا إلا إذا بلغ درجة معينة من الاستقرار أو توافرت حالة من الحالات الأولى بالرعاية من مسألة الاستقرار هذه."},{"kind":"text","text":"فالقاعدة أن الحكم القضائي لن يكون سندا تنفيذيا إلا إذا كان نهائيا وليس ابتدائيا. والاستثناء أن الحكم الابتدائي يكون سندا تنفيذيا في بعض الحالات المسماة بحالات النفاذ المعجل."},{"kind":"text","text":"القاعدة أنه يجب أن يكون الحكم نهائيا (أي حائزا لقوة الأمر المقضي فيه)"},{"kind":"text","text":"18- من أشهر التقسيمات التي تعرفها النظرية العامة للأحكام القضائية هي تقسيم الأحكام بحسب درجة الاستقرار الإجرائي التي بلغها الحكم. ويقصد بدرجة الاستقرار الإجرائي مدى قابلية الحكم للطعن، وما إذا كان هذا الطعن عاديا أم غير عادي. ووفقا لهذا المعيار تنقسم الأحكام القضائية إلى أحكام ابتدائية وأحكام نهائية وأحكام باتة."},{"kind":"text","text":"فالحكم البات هو ولا شك أكثر الأحكام استقرارا. ذلك لأن الوسيلة الوحيدة للنيل من حجية الأحكام أو وجوده أصلا هي الطعن عليه، والحكم يكون باتا بعد أن يصير غير قابل للطعن عليه بأي طريق من طرق الطعن عادية كانت أم غير عادية. ولذلك لا يثور شك حول القوة التنفيذية للحكم البات، وعلى افتراض أنه مستجمع للشروط الأخرى للسند التنفيذي. ينطبق ذلك أولا على الحكم الصادر من المحاكم العليا عندما تفصل في الموضوع. كما ينطبق ثانيا على الأحكام الصادرة من محاكم الاستئناف عندما يكون الطعن عليها بالنقض أو الالتماس غير جائز. كما ينطبق ثالثا على الأحكام الصادرة من المحاكم الابتدائية التي لا تقبل الطعن عليها بأي طريق، أو بطريق الاستئناف على الأقل. كما ينطبق ذلك أيضا على الحكم الصادر من دائرة التركات. ولا يغير من كل ذلك قابلية الحكم البات للرجوع فيه أو السحب من جانب المحاكم العليا."},{"kind":"text","text":"ما سبق كان عن الحكم البات."},{"kind":"text","text":"19- والأهم منه في مجال التنفيذ الجبري هو الحكم النهائي. ذلك لأن القانون لا يتطلب درجة البتية في الحكم لكي يكون سندا تنفيذيا، وإنما يكتفي بدرجة النهائية. ويكون الحكم نهائيا إذا كان غير قابل للطعن عليه بالاستئناف. وهو لا يقبل الطعن بالاستئناف إما لأنه صادر من محكمة الاستئناف، فالاستئناف على الاستئناف لا يجوز، وإما لأنه صادر من محكمة ابتدائية إلا أن الطعن عليه بالاستئناف يكون غير مقبول."},{"kind":"text","text":"ويعتبر الحكم النهائي- وأيا كان سبب نهائيته- مستوفيا للشرط الثالث من شروط الحكم القضائي كسند تنفيذي، حتى ولو كان قابلا لطعن غير عادي. فصفة النهائية هي القاعدة العامة المعتمدة لكي يكتسب الحكم القضائي القوة التنفيذية. ويمكن التعبير عن النهائية أيضا بعبارة قوة الأمر المقضي."},{"kind":"text","text":"ما سبق كان عن الحكم النهائي."},{"kind":"text","text":"ولكن ماذا عن الحكم الابتدائي؟ هل يصلح هو الآخر لكي يكون سندا تنفيذيا؟ الإجابة تستدعي تفصيلا يستحق أن يخصص له مطلب مستقل، تحت عنوان النفاذ المعجل."},{"kind":"heading","text":"المطلب الثاني: النفاذ المعجل"},{"kind":"text","text":"20- الحكم الابتدائي هو الحكم الصادر من المحكمة الابتدائية- أي تلك التي تختص بالدعاوى المرفوعة للمرة الأولى- ويكون قابلا للطعن بالاستئناف، مع ملاحظة أن القابلية لهذا الطعن هي أصل عام."},{"kind":"text","text":"والمفروض ألا يكون للحكم الابتدائي قوة تنفيذية، فهو أقل الأحكام استقرارا. ذلك لأن المفروض ألا يكون للحكم هذه القوة إلا إذا كان الحق الثابت فيه قويا هو الآخر. وتعزى قوة الحق هنا إلى درجة الاستقرار التي يبلغها الحكم. فالحكم النهائي - أو البات من باب أولى- قد بلغ درجة معقولة من الاستقرار نتيجة عدم جواز المساس به من خلال طريق الطعن العادي وهو الاستئناف، لذلك فهو يتمتع بالقوة التنفيذية، بينما الحكم الابتدائي لم يبلغ هذه الدرجة من الاستقرار، نظرا لقابليته لهذا الطعن العادي، وحيث يمكن الاستناد فيه لأي سبب من أجل إلغائه."},{"kind":"text","text":"ولا شك في صوابية هذا التوجه من جانب المشرع، فدرجة النهائية- أو قوة الأمر المقضي- هي وسط بين الابتدائية والبتية، وبالتالي تحقق درجة معقولة من الاستقرار بغير تفريط أو تشدد. فمصلحة المحكوم له أن يكون للحكم قوة تنفيذية ولو كان ابتدائيا، بينما مصلحة المحكوم عليه ألا يكون للحكم هذه القوة إلا إذا كان باتا. والتوفيق بين المصلحتين اقتضى الوقوف عند درجة النهائية."},{"kind":"text","text":"على أنه إذا كان المشرع لا يعتبر الحكم الابتدائي سندا تنفيذيا كأصل عام. إلا أنه أورد على هذه القاعدة استثناء محددا يكون فيه الحكم الابتدائي سندا تنفيذيا. ولأن اكتساب الحكم للقوة التنفيذية في هذه الحالة يعتبر سابقا لأوانه الطبيعي- إذ يكتسبها قبل أن يكون نهائيا- سميت القوة التنفيذية لهذا الحكم بالنفاذ المعجل."},{"kind":"text","text":"وبطبيعة الحال لا يوجد محل للحديث عن النفاذ المعجل للحكم الابتدائي إلا إذا كان هذا الأخير صادرا بإلزام. أما إذا كان تقريريا أو إنشائيا، فلا يجوز شموله بالنفاذ المعجل. إذ لا مجال للحديث عن النفاذ المعجل إلا بمناسبة السند التنفيذي والذي لا يتوافر إلا بمناسبة حكم الإلزام. أما الحكم التقريري أو الإنشائي فهو يرتب آثاره- والتي ليس منها القوة التنفيذية- بمجرد النطق به ودون الحاجة إلى عرضه على نظرية السند التنفيذي."},{"kind":"text","text":"سوف نتعرف على المقصود بالنفاذ المعجل والحكمة منه، ثم على نوعي النفاذ المعجل وهما النفاذ المعجل القانوني والنفاذ المعجل القضائي، وحالات كل منهما، ثم نتساءل عن مدى جواز الاتفاق على شمول الحكم بالنفاذ المعجل، لنتعرض بعد كل ما سبق لنظام الكفالة الذي قد يصاحب النفاذ المعجل."},{"kind":"text","text":"الفرع الأول: تعريف النفاذ المعجل والحكمة منه"},{"kind":"text","text":"21- لن يكون مستغربا أن يسمح المشرع بإكساب الحكم الابتدائي للقوة التنفيذية في بعض الحالات التي يكون الحق فيها قويا. فعندما يضع المشرع يده على دلائل تشير إلى أن الاستئناف رغم جوازه لن ينال من الحق الثابت في الحكم الابتدائي، سوف تتوافر علة للخروج على القاعدة العامة، وإيجاد آلية لاعتبار هذا الحكم سندا تنفيذيا."},{"kind":"text","text":"ولن يكون مستغربا أيضا أنه حتى ولو ظل الحكم ابتدائيا ودون أن يتوافر معه الدليل على أن الحق الثابت فيه قويا، إلا أنه من الممكن أن تتوافر علة أخرى للخروج على القاعدة العامة. هذه العلة الأخرى هي حاجة المحكوم له في بعض الأحوال للحصول على حماية تنفيذية سريعة بمجرد صدور الحكم الابتدائي، رغم جواز استئنافه، ودون البحث في مسألة الدلائل التي ترجح أنه سيتأيد من محكمة الطعن هذه."},{"kind":"text","text":"في مثل هذه الحالات أو تلك، أوجد المشرع الآلية التي يكتسب الحكم الابتدائي بها قوة تنفيذية تسمى بالنفاذ المعجل، تماثل تلك التي يتمتع بها الحكم النهائي. الفارق الوحيد أن الحكم الابتدائي المشمول بالنفاذ المعجل يكون رغم قابليته للتنفيذ قابلا في نفس الوقت للطعن بالاستئناف، بينما الحكم النهائي يعتبر قابلا للتنفيذ نظرا لعدم قابليته للطعن بالاستئناف."},{"kind":"text","text":"والحكم القضائي يكون مشمولا بالنفاذ المعجل إما بقوة القانون وإما بأمر القضاء. وبناء عليه ينقسم النفاذ المعجل للحكم إلى نفاذ معجل قانوني ونفاذ معجل قضائي."},{"kind":"text","text":"الفرع الثاني: النفاذ المعجل القانوني (أو بقوة القانون)"},{"kind":"text","text":"22- يكون الحكم الابتدائي مشمولا بالنفاذ المعجل القانوني عندما يكتسب هذه الصفة بقوة القانون. فقد أراد المشرع شمول الحكم بالنفاذ المعجل في بعض الأحوال، بل وأراد أن يكون هذا النفاذ واجبا دون حاجة إلى نطق القاضي به، وبالتالي دون حاجة إلى طلبه من جانب ذوي الشأن."},{"kind":"text","text":"وقد ساعد المشرع على ذلك أن حالات النفاذ المعجل بقوة القانون التي اختارها هي حالات يسهل على سلطة التنفيذ- وكذلك الموظف المختص بوضع الصيغة التنفيذية- التعرف على الحكم الصادر فيها بمجرد الاطلاع، رغم أنه لا يتضمن عبارة النفاذ المعجل. فمن حالات النفاذ المعجل القانوني مثلا الحكم الصادر في مادة مستعجلة. فلأنه يسهل التعرف على الحكم بأنه مستعجل، كان من السهل أيضا النص على أن هذا الحكم يعتبر مشمولا بالنفاذ المعجل بقوة القانون. وسوف نزيد- حالا- هذه المسألة إيضاحا."},{"kind":"text","text":"حالات النفاذ المعجل القانوني"},{"kind":"text","text":"حددت المادة 1-215، أ، ب، ج، د الأحكام المشمولة بالنفاذ المعجل بقوة القانون. على أن هذا التحديد ليس حصريا، إذ لا مانع من وجود نص في أي تشريع آخر يضيف إلى ذلك حكما آخر."},{"kind":"text","text":"على أي حال، فإن ما حددته المادة المذكورة هو:"},{"kind":"heading","text":"1 - الأحكام المستعجلة"},{"kind":"text","text":"23- ذكر المشرع صراحة \"الأحكام الصادرة في المواد المستعجلة أيا كانت المحكمة التي أصدرتها\" (مادة 1- 215 -أ) كأول حالة من حالات النفاذ المعجل القانوني."},{"kind":"text","text":"والحكم المستعجل الذي سيكون مشمولا بالنفاذ المعجل بقوة القانون ليس بطبيعة الحال عموم الحكم الصادر في الدعوى المستعجلة، وإنما فقط ما تتوافر فيه أيضا باقي الشروط المطلوبة في الحكم القضائي لكي يكون سندا تنفيذيا."},{"kind":"text","text":"أما إذا توافرت في الحكم المستعجل شرائط السند التنفيذي الأخرى- بأن كان صادرا بإلزام وفي موضوع الدعوى المستعجلة - فإنه يكون مشمولا بالنفاذ المعجل القانوني، رغم صدوره ابتدائيا في جميع الأحوال، وأيا كانت المحكمة التي أصدرته. ويقصد بهذه العبارة الأخيرة، أنه يستوي أن يكون الحكم المستعجل صادرا من قاضي الأمور المستعجلة، أم صادرا من محكمة الموضوع التي اختصت بالدعوى المستعجلة التي رفعت إليها بطريق التبعية للدعوى الموضوعية تطبيقا لنص المادة 2- 28 من القانون."},{"kind":"heading","text":"2- الأحكام الصادرة بالنفقات"},{"kind":"text","text":"24- الحالة الثانية من حالات النفاذ المعجل بقوة القانون هي\" الأحكام الصادرة في دعاوى الأحوال الشخصية بالنفقات والأجور وما يرتبط بها من مصروفات وزيادتها أو تخفيضها \" (مادة 1- 215 -ب)."},{"kind":"text","text":"إذا بدأنا بشق من العبارة المذكورة، وتحديدا المتعلق بالأحكام الصادرة بالنفقات وزيادتها أو تخفيضها، فإن شمول هذه الأحكام بالنفاذ المعجل القانوني يكون مقيدا بالضوابط الآتية:"},{"kind":"text","text":"فمن ناحية أولى، نحن أمام حكم صادر بأداء النفقة أو زيادتها أو تخفيضها، وليس مطلق الأحكام الصادرة في دعاوى النفقة. فالحكم الصادر برفض الدعوى مثلا لا يكون مشمولا بالنفاذ المعجل، فهو حكم تقريري وليس حكما بإلزام."},{"kind":"text","text":"ومن ناحية ثانية، نحن بصدد حكم صادر بالنفقة الموضوعية، أي النفقة المسماة بالمرتبة أو المقررة وليس عموم النفقة. فالحكم الصادر بالنفقة الوقتية لا يدخل في العبارة محل البحث."},{"kind":"text","text":"ومن ناحية ثالثة، نحن بصدد حكم بالنفقة في دعوى من دعاوى الأحوال الشخصية. ولذلك يستوي أن يكون نفقة للزوجة أو المطلقة أو الأولاد أو الأقارب. أما نفقة المتعة فهي ليست من النفقات بالمعنى الفني الدقيق وإنما هي من التعويضات، ولذلك لا تشملها العبارة محل البحث."},{"kind":"text","text":"نصل الآن إلى الجزء الثاني من العبارة الواردة في البند محل البحث، وهي تشمل الأحكام الصادرة بالمصروفات أو الأجور."},{"kind":"text","text":"ويقصد بالمصروفات، نوع من النفقات، كمصروفات تعليم الأولاد أو علاجهم أو تنقلاتهم أو خدمتهم."},{"kind":"text","text":"وأخيرا يقصد بالأجور، نوع ثالث من النفقات أيضا، مثل أجرة الحضانة أو الرضاعة أو السكن."},{"kind":"heading","text":"3- الأحكام الصادرة بتسليم الصغير أو رؤيته أو زيارته أو اصطحابه"},{"kind":"text","text":"25- أول ما يلاحظ على هذه الأحكام أنها لا تتناول الحضانة في ذاتها. ذلك لأن الحكم الصادر بتحديد من يتولى حضانة الصغير هو حكم تقريري أو إنشائي بحسب الأحوال دون أن يتضمن أي إلزام، ومن ثم لا يحتاج إلى تنفيذ جبري، وبالتالي لا يحتاج إلى استحضار فكرة النفاذ المعجل. هذا مع ملاحظة أنه يرتب آثاره فور صدوره وفقا للقاعدة العامة في ترتيب الأحكام لآثارها غير التنفيذية."},{"kind":"text","text":"فالمقصود بالأحكام محل البحث هنا هي تلك التي تتناول أمورا أخرى قد تترتب على الحضانة. فالحكم- أو شق الحكم- الذي يصدر بإلزام ويحتاج بالتالي إلى الشمول بالنفاذ المعجل، هو ما يصدر عادة بمناسبة الحضانة من تسليم أو رؤية أو زيارة أو اصطحاب للصغير. وقد قرر المشرع بالفعل شمول الحكم الابتدائي الصادر في أي من هذه الأحوال بالنفاذ المعجل بقوة القانون (مادة 1- 215 -ج)."},{"kind":"text","text":"الفرع الثالث: النفاذ المعجل القضائي"},{"kind":"text","text":"26- يكون الحكم مشمولا بالنفاذ المعجل القضائي عندما ترد فيه عبارة تفيد أنه مشمول بالنفاذ المعجل. فعلى خلاف النفاذ المعجل القانوني، توجد حالات يستمد فيها الحكم الابتدائي قوته التنفيذية ليس بقوة القانون وإنما من ذكر القاضي لعبارة \"مع شمول الحكم بالنفاذ المعجل\"."},{"kind":"text","text":"وحتى يكون احتواء الحكم على هذه العبارة موافقا لصحيح القانون، يجب أن تتوافر الشروط الثلاثة الآتية:"},{"kind":"text","text":"27- الشرط الأول: أن يطلب أحد الخصوم من المحكمة شمول حكمها بالنفاذ المعجل. فالفرض أن هناك دعوى مرفوعة بطلب ما، وبمناسبتها يطلب المدعي أيضا شمول الحكم الذي سيصدر في موضوعها بالنفاذ المعجل. يستوي بعد ذلك أن يكون هذا الطلب الأخير مقدما في صحيفة الدعوى أو مقدما في وقت لاحق أثناء الخصومة."},{"kind":"text","text":"ليس مقبولا إذا تقديم الطلب في خصومة مستقلة، أو بعد صدور الحكم واستنفاد المحكمة بالتالي لولايتها. وحتى قبل ذلك، ليس للمحكمة الحكم بالنفاذ المعجل من تلقاء نفسها، حتى ولو توافرت إحدى حالاته."},{"kind":"text","text":"28- الشرط الثاني: أن تقرر المحكمة الاستجابة لطلب النفاذ المعجل. فتقديم الطلب وتوافر حالة من حالات النفاذ المعجل- التي سنتعرف عليها حالا- لا يجعل هذا الأخير وجوبيا، وإنما يظل الحكم به موقوفا على سلطة المحكمة التقديرية، والتي لها رفضه صراحة أو ضمنا، وعندئذ لن نكون أمام نفاذ معجل. وليس هناك شك في أن النفاذ المعجل القضائي في التشريع الإماراتي يعد جوازيا وليس وجوبيا، فالمادة 216 تبدأ بعبارة \"يجوز للمحكمة.. شمول حكمها بالنفاذ المعجل..\"."},{"kind":"heading","text":"29- الشرط الثالث: أن تتوافر حالة من حالات النفاذ المعجل القضائي. هذه الحالات هي:"},{"kind":"heading","text":"1- الأحكام الصادرة في المواد التجارية."},{"kind":"text","text":"30- يقصد بذلك أحكام الإلزام الموضوعية التي تفصل في منازعة تجارية، أي منازعة يتم الفصل فيها استنادا إلى نصوص القانون التجاري- بالمعنى الواسع- وقواعده. مثال ذلك الحكم الصادر بإلزام التاجر- فردا كان أو شركة- بدفع دين تجاري."},{"kind":"text","text":"والحكمة التي استدعت دخول هذه الحالة ضمن النفاذ المعجل، هي اعتماد المعاملات التجارية على عنصر السرعة، وبالتالي ضرورة الأخذ في الاعتبار حاجة المحكوم له إلى حماية تنفيذية سريعة."},{"kind":"heading","text":"2- الحكم المبني على إقرار."},{"kind":"text","text":"31- يقصد بذلك تحديدا الحكم الصادر ضد المدعى عليه واستند في أسبابه إلى إقراره بنشأة الالتزام، رغم عدم ثبوته في ورقة مكتوبة. فلأن الحق يستمد قوته من دليله، ولأن الإقرار القضائي من أدلة الإثبات الحاسمة وغير القابلة للعدول عنها، فإن الحق الثابت في الحكم المبني على إقرار يعتبر حقا قويا، واحتمالات إلغائه في الاستئناف تبدو ضعيفة، ولذلك كان منطقيا أن يجيز المشرع شمول الحكم الابتدائي في هذه الحالة بالنفاذ المعجل."},{"kind":"text","text":"ويفترض في الحكم المبني على إقرار هنا أن المحكوم عليه كان قد أقر بنشأة الالتزام، وفي ذات الوقت نازع في نطاقه أو في بقائه في ذمته. ذلك لأنه إذا كان إقراره غير مشروط، فإن الحكم الصادر بناء عليه يكون نهائيا، ولا حاجة لشموله بالنفاذ المعجل."},{"kind":"heading","text":"3- الحكم المبني على سند رسمي."},{"kind":"text","text":"32- يعتبر الحق الثابت في هذا الحكم هو الآخر حقا قويا نظرا لقوة السند الرسمي في الإثبات. ولذلك ساير المشرع منطقه الذي كان وراء الحالة المذكورة سابقا، وجعل الحكم المبني على سند رسمي ضمن حالات النفاذ المعجل. ومما يساهم في قبول هذه النتيجة، أنه يشترط لتوافر الحالة محل البحث، أن المدعى عليه الذي صدر ضده الحكم كان طرفا في السند ولم يطعن بتزويره (مادة 3- 216)."},{"kind":"heading","text":"4- الحكم المبني على سند عرفي."},{"kind":"text","text":"33- لذات العلة السابقة تم إدخال هذه الحالة ضمن حالات النفاذ المعجل. ولذلك كان من الشروط أيضا أن يكون المحكوم عليه طرفا في السند ولم يجحده. أما إذا كان السند العرفي مجحودا، ويكفي لذلك أن ينكر الخصم نسبته إليه، فإنه لن تتوافر الحالة محل البحث، نظرا لأن مجرد الجحود يهدم قوة الورقة العرفية في الإثبات. على أنه سوف يختلف الحال إذا تم دحض هذا الجحود بثبوت صحة التوقيع."},{"kind":"heading","text":"5- الحكم الصادر تنفيذا لحكم سابق."},{"kind":"text","text":"34- هذه هي المرة الرابعة التي ينبني فيها النفاذ المعجل على قوة سند الحق. هذا السند الأخير هو هذه المرة حكم قضائي سابق. ولأن حيازته لحجية الأمر المقضي ترتب أثرا إيجابيا يتمثل في ضرورة احترام ما قضى به، وذلك عند الفصل في أي دعوى أخرى لاحقة ومتفرعة، فإن الحق الذي سيفصل فيه الحكم الذي سيصدر في هذه الأخيرة سيكون حقا قويا لاستناده إلى الحق الثابت في الحكم الأول، وهو ما يعبر عنه النص بأن الحكم الثاني يعتبر تنفيذا للحكم الأول. وهو ليس التنفيذ الجبري بالمعنى الفني الدقيق وإنما مجرد الحكم بأداء يعد نتيجة مترتبة عليه. مثال ذلك أن يصدر أولا حكم بصحة العقد، ثم يصدر حكم لاحق بإلزام أحد الطرفين بالوفاء بالتزامه الناشئ عن هذا العقد. فهذا الحكم الأخير هو بمثابة حكم صدر تنفيذا لحكم سابق."},{"kind":"text","text":"ولكي تتوافر الحالة محل البحث لا يكفي أن يكون الحكم السابق حائزا لحجية الأمر المقضي- تلك الحجية التي تتوافر في كل حكم موضوعي ولو كان ابتدائيا- وإنما تطلب المشرع في هذا الحكم أن يكون من الصعب إلغاؤه، ويكون الحق الثابت به بالتالي حقا قويا. عبر المشرع عن ذلك بأن تطلب في الحكم السابق أن يكون إما حائزا لقوة الأمر المقضي أو مشمولا بالنفاذ المعجل بغير كفالة (مادة 3-216). فعندما يكون الحكم السابق حائزا لقوة الأمر المقضي- وهو تعبير مرادف للنهائية في علم القضاء المدني الإماراتي- فإنه يكون غير قابل للإلغاء بطريق طعن عادي، وبالتالي فإن احتمالية إلغائه أقل بكثير مما لو كان قابلا للإلغاء بهذا الطريق. وعندما يكون الحكم السابق مشمولا بالنفاذ المعجل بغير كفالة، فإن احتمالات إلغائه في الاستئناف هي الأخرى تكون قليلة، إذ نفاذه معجلا يعني غالبا أنه مبني على سند قوي، ونفاذه بغير كفالة يؤكد غالبا هذا المعني. أما إذا كان الحكم السابق حكما ابتدائيا محضا- أو مشمولا بالنفاذ ولكن مع كفالة- فإن الحالة محل البحث لا تعد متوافرة."},{"kind":"heading","text":"6- الحكم الصادر لمصلحة طالب التنفيذ في منازعة تنفيذ."},{"kind":"text","text":"35- تفترض هذه الحالة من حالات النفاذ المعجل القضائي أن هناك دعوى إلزام من دعاوى التنفيذ الموضوعية، وأن طالب التنفيذ كان طرفا في هذه المنازعة- وهو بالفعل كذلك في أي منازعة تنفيذ- وطلب أن يتم شمول الحكم الذي سيصدر فيها بالنفاذ المعجل. إذا رأت المحكمة الحكم في الموضوع بالفعل لمصلحته، أمكنها أن تشمل حكمها هذا بالنفاذ المعجل. مثال ذلك الحكم الصادر بإلزام المحجوز لديه بأداء الدين المحجوز من أجله عند ثبوت إخلاله بواجب التقرير بما في الذمة."},{"kind":"heading","text":"7- الحكم الصادر بأداء أجور أو راتب أو تعويض ناشئ عن علاقة عمل."},{"kind":"text","text":"36- تعتبر دعاوى المطالبة بالأجور أو المرتبات أو بملحقاتها أو بالتعويض الناشئ عن علاقة عمل من أشهر الدعاوى العمالية. ولا شك في حاجة العامل أو الموظف المحكوم له في هذه الدعاوى إلى حماية تنفيذية سريعة. ولذلك جعل المشرع هذه الحالة ضمن حالات النفاذ المعجل القضائي."},{"kind":"text","text":"ولا يدخل في مفهوم دعاوى الأجور دعاوى المطالبة بالعلاوة أو مكافأة نهاية الخدمة."},{"kind":"text","text":"بينما يدخل في مفهوم دعاوى التعويض الناشئ عن علاقة عمل، أولا طلب التعويض الناشئ عن إصابة عمل، وثانيا طلب التعويض عن الفصل التعسفي."},{"kind":"heading","text":"8- الحكم الصادر بإخراج شاغل العقار دون سند."},{"kind":"text","text":"37- شاغل العقار دون سند قد يكون أولا مستأجر العقار الذي انتهى عقده لأي سبب من الأسباب ومنها الفسخ بطبيعة الحال، وقد يكون ثانيا مغتصب حيازة العقار، وقد يكون ثالثا من زالت ملكيته للعقار. في كل هذه الأحوال يحتاج المحكوم له بإخراج شاغل العقار إلى حماية تنفيذية سريعة حتى لا يحدث اضطراب للأمن الاجتماعي إذا حدث احتكاك بين الأطراف. ولذلك نص المشرع على هذه الحالة ضمن حالات النفاذ المعجل."},{"kind":"heading","text":"9- الحكم الصادر في أية حالة يترتب على تأخير التنفيذ فيها ضرر جسيم بمصلحة المحكوم له."},{"kind":"text","text":"38- هذه الحالة هي من العمومية بحيث تجعل حالات النفاذ المعجل القضائي وكأنها ليست واقعة تحت حصر. فيكفي أن المدعي المحكوم له كان قد أثبت في دعواه أن هناك ضررا غير عادي سوف يصيبه لو انتظر حتى يصير الحكم نهائيا، وذلك لكي يستجيب القاضي- إن شاء- لطلبه بشمول الحكم الابتدائي بالنفاذ المعجل، فلا يتأخر التنفيذ ولا يحدث هذا الضرر الجسيم."},{"kind":"text","text":"الفرع الرابع: مدى جواز الاتفاق على شمول الحكم بالنفاذ المعجل"},{"kind":"heading","text":"39- تنص المادة 2- 217 على أنه \"لا يجوز الاتفاق قبل صدور الحكم على شموله بالنفاذ المعجل في غير حالة من حالاته\"."},{"kind":"text","text":"والمعنى المستفاد بكل وضوح من عبارة النص أنه لا يجوز الاتفاق مقدما على شمول الحكم بالنفاذ المعجل. فهل هذا الوضوح موجود أيضا وبنفس الدرجة عندما يكون الاتفاق على النفاذ المعجل لاحقا على صدور الحكم؟"},{"kind":"text","text":"(أ) الصياغة قطعية الدلالة فيما يتعلق بعدم جواز الاتفاق المسبق:"},{"kind":"text","text":"40- فعبارة المادة المذكورة تصرح بعدم جواز الاتفاق على شمول الحكم بالنفاذ المعجل إذا كان هذا الاتفاق \"سابقا\" على صدور الحكم. يستوي بعد ذلك أن يكون هذا الاتفاق الباطل متعلقا بالنفاذ المعجل القانوني أو القضائي. يعتبر باطلا إذا الاتفاق مقدما على أن يكون الحكم الابتدائي الذي سيصدر في نزاع معين قابلا للتنفيذ، دون المساس بقابليته للاستئناف في الوقت ذاته. وهذا البطلان من النظام العام نظرا لتعلق قواعد التنفيذ- ومنها بالطبع تلك التي تحدد شروط السند التنفيذي- بالنظام العام."},{"kind":"text","text":"ويلاحظ أن صياغة النص جاءت بعبارة مقيدة. فقد اقتصر النص على التعرض لعدم جواز الاتفاق السابق على شمول الحكم بالنفاذ المعجل “في غير حالة من حالاته\". ومع ذلك يجب أن يكون المعنى المستفاد من العبارة طليقا. ذلك لأن الاتفاق على النفاذ المعجل \"في حالة من حالاته\" ليست له أية فائدة خاصة، وبالتالي لا يتوقع من الأطراف إبرامه. إذ لا قيمة لوجود اتفاق مسبق أو غيابه، إذا كنا أمام نفاذ معجل قانوني، أو حالة من حالات النفاذ المعجل القضائي المنصوص عليها."},{"kind":"text","text":"(ب) الصياغة ظنية الدلالة -لاعتمادها على مجرد مفهوم المخالفة- فيما يتعلق بمدى جواز الاتفاق اللاحق:"},{"kind":"text","text":"41- اقتصرت عبارة المادة 2-217 على عدم جواز الاتفاق\" قبل صدور الحكم\". أما الاتفاق اللاحق على أن يكون الحكم مشمولا بالنفاذ المعجل، فإن العبارة المذكورة لا تشمله. ولذلك يمكن انطلاقا من مفهوم المخالفة القول بجواز هذا الاتفاق اللاحق. ومؤدى هذا الاتفاق أن الحكم هنا سيقبل التنفيذ، ويقبل في الوقت ذاته الطعن بالاستئناف."},{"kind":"text","text":"وقد يبدو لأول وهلة أن هذا التحليل ليس مستساغا. ذلك لأن الاتفاق اللاحق لن يكون اتفاقا على نفاذ معجل، نظرا لأنه سيجعل الحكم نهائيا. فالاتفاق على شمول الحكم بالنفاذ المعجل بعد صدوره يحمل في طياته قبولا من جانب المحكوم عليه بتنفيذه، وهذا القبول بالتنفيذ هو قبول ضمني بالحكم ذاته، وهو ما سيجعله قابلا للتنفيذ، ليس باعتباره مشمولا بالنفاذ المعجل، وإنما باعتباره حكما صار نهائيا. وهذه النهائية تجعل الحديث عن النفاذ المعجل لغوا. فليس هناك نفاذ معجل معقول المعنى إلا لو ظل الحكم ابتدائيا- وليس نهائيا- يقبل الاستئناف. ولعل ما سبق يفسر السبب الذي جعل المادة 2-217 تتعرض فقط للاتفاق السابق، فالاتفاق اللاحق ليس له أي محل."},{"kind":"text","text":"مثل هذا الاعتراض الذي قد يثور في ذهن البعض لا يستعصي على الرد. ذلك لأن المشرع الذي وضع القاعدة المتضمنة لقرينة أن القبول بالتنفيذ قبول بالحكم ومن ثم نهائيته، هو نفسه الذي وضع عليها أيضا استثناء. فالمادة 2-151 من القانون التي قررت أن قبول الحكم مانع من الطعن عليه هي نفسها تشير إلى ضرورة مراعاة وجود نص يقرر غير ذلك. ويعتبر نص المادة 2-217 مما يجب مراعاته في هذا الصدد. فهو لا يجعل القبول هنا مانعا من الطعن. ولذلك يظل الاتفاق على شمول الحكم بالنفاذ المعجل معقول المعنى، ويجب الاعتداد به، طالما كان لاحقا على صدور الحكم."},{"kind":"text","text":"الفرع الخامس: الكفالة في النفاذ المعجل"},{"kind":"text","text":"43- جرت عادة النصوص القانونية على تحميل المدين وليس الدائن، بعبء تقديم الكفالة. ولذلك لن يكون متوقعا أن يصدر حكم لصالح الدائن المحكوم له، ويلزمه هو- وليس المحكوم عليه- بتقديم كفالة."},{"kind":"text","text":"ومع ذلك قد يتضمن القانون حلا مغايرا، وذلك عندما نكون أمام دائن قد ينقلب في وقت لاحق إلى مدين. فقد أجازت المادتان 215 و216 إلزام الدائن بتقديم كفالة بمناسبة الحكم الصادر لصالحه، عندما يكون هذا الحكم مشمولا بالنفاذ المعجل. ويجد هذا الحل تبريره في أنه سيسمح لهذا الدائن بتنفيذ حكم قابل للاستئناف، وبالتالي قابل للإلغاء هو والتنفيذ. فإذا حدث الإلغاء، صار هذا الدائن ملزما بإعادة الحال إلى ما كان عليه أي صار مدينا. ومما يضمن إعادة الحال هنا هو الكفالة التي سبق له تقديمها حين كان دائنا محكوما له بمقتضى الحكم المشمول بالنفاذ المعجل."},{"kind":"text","text":"والكفالة على هذا النحو تمثل عبئا على المحكوم له عندما يكون ملزما بتقديمها. إذ لن يكون بإمكانه تنفيذ الحكم معجلا إلا إذا أوفى أولا بهذا الالتزام. وقد يعجزه ذلك عن الاستفادة من النفاذ المعجل. معنى ذلك أن الحكمة التي من أجلها شرع نظام النفاذ المعجل تصطدم مع شرط الكفالة، والذي قد يجعل النفاذ المعجل عقيما."},{"kind":"text","text":"44- وحتى لا نصل إلى هذه النتيجة غير المرغوب فيها، أحاطت النصوص نظام الكفالة التي سيحمل بها المحكوم له بجملة خواص تسمح له بالتعايش المشترك مع نظام النفاذ المعجل في تناغم يحمد عليه المشرع."},{"kind":"text","text":"فمن ناحية أولى، لم يشأ المشرع أن يجعل الكفالة مصاحبة للنفاذ المعجل في جميع الأحوال، وإنما على العكس جعلها استثناء، فالمبدأ أن النفاذ المعجل هو بغير كفالة. فحتى النفاذ المعجل القانوني هو بغير كفالة ما لم ينص في الحكم على تقديم كفالة (مادة 2- 215). وكذلك الشأن في النفاذ المعجل القضائي (مادة 216). الكفالة إذا كأصل عام قضائية، كما أنها كأصل عام جوازية، حتى ولو كان الحكم مشمولا بالنفاذ المعجل القانوني."},{"kind":"text","text":"ومن ناحية ثانية، لم يشأ المشرع أن يحصر الكفالة في صورة واحدة قد تستعصي على الملزم بها، وإنما أعطى له الخيار بين عدة صور، واحدة منها- سنتعرف عليها لاحقا- مقدور عليها في جميع الأحوال. مثل هذا التنظيم يجعل الحكم المشمول بالنفاذ المعجل مع كفالة، قابلا للتنفيذ دون عائق."},{"kind":"text","text":"ومن ناحية ثالثة، كان من المنطقي أن يعلق المشرع التنفيذ على عدم المنازعة في الكفالة. إلا أنه لم يشأ أن يجعل هذه المنازعة إن حدثت معطلة للتنفيذ لوقت طويل. فقد نظم المشرع المنازعة في الكفالة بحيث تتم تصفيتها خلال بضعة أيام، ويكون الطريق بعدها ممهدا للتنفيذ المعجل بالفعل."},{"kind":"text","text":"صور الكفالة"},{"kind":"heading","text":"45- تتضمن المادة 218 صورا أربعة للكفالة، تعتبر على سبيل الحصر، هي:"},{"kind":"text","text":"1-الكفالة الشخصية"},{"kind":"text","text":"للملزم بالكفالة أن يختار تقديم كفيل مقتدر (مادة 218). عندئذ يكفي أن يتعهد هذا الكفيل الشخصي بالكفالة أمام قاضي التنفيذ، ويكون المحضر المشتمل على تعهده هذا بمثابة سند تنفيذي قبله بالالتزامات المترتبة على ذلك (مادة 4- 219)."},{"kind":"heading","text":"2- الكفالة المالية"},{"kind":"text","text":"يقصد بذلك أن يقوم الملتزم بالكفالة بإيداع مبلغ من النقود أو الأوراق المالية في خزانة المحكمة (مادة 218). ويجب أن يكون هذا المبلغ كافيا لإعادة الحال إلى ما كان عليه. وهو يكون كذلك لو كان على الأقل مساويا لقيمة الدين المراد التنفيذ من أجله والمصروفات."},{"kind":"heading","text":"3- قبول إيداع ما يحصل من التنفيذ خزانة المحكمة"},{"kind":"text","text":"الفرض الآن أن الأداء المطلوب من المحكوم عليه هو دفع مبلغ من النقود. عندئذ سيجري التنفيذ بالحجز على أمواله وبيعها بالمزاد مقابل ثمن هو بالتأكيد مبلغ من النقود. ولذلك يكفي أن يعلن الملزم بالكفالة قبوله إيداع حصيلة التنفيذ خزانة المحكمة لكي يعتبر التزامه بالكفالة قد استوفي."},{"kind":"heading","text":"4- قبول إيداع الشيء المأمور بتسليمه إلى حارس أمين"},{"kind":"text","text":"الفرض الآن أن الأداء المطلوب من المحكوم عليه ليس دفع مبلغ من النقود وإنما أي أداء آخر كتسليم شيء معين مثلا. عندئذ يكون للملزم بالكفالة أن يختار قبول تسليم هذا الشيء لحارس أمين. فإذا تعهد الحارس بقبول الحراسة أمام قاضي التنفيذ، فإن المحضر المشتمل على قبوله هذا يعتبر بمثابة سند تنفيذي قبله بالالتزامات المترتبة على ذلك (مادة 4-219)."},{"kind":"text","text":"المنازعة في الكفالة"},{"kind":"text","text":"46- عندما يكون الحكم المشمول بالنفاذ المعجل مقرونا بكفالة، فمن المفروض أن يكون تنفيذه ممتنعا إلى أن تتحقق صورة من صور الكفالة السابقة. وحتى يحدث ذلك، يجب على الملزم بالكفالة إعلان خياره إلى المحكوم عليه، إذ تجب ملاحظة أن القاضي لا يحدد صورة الكفالة، وإنما الخيار متروك للمحكوم له. وهو يقوم بإعلان خياره إما على يد مندوب التنفيذ بورقة مستقلة، وإما ضمن إعلان السند التنفيذي (مادة 1- 219)."},{"kind":"text","text":"ولا يكفي إعلان الخيار بالكفالة حتى يكون البدء في التنفيذ جائزا، وإنما يجب انتظار ثلاثة أيام على الأقل تحسب من تاريخ الإعلان، يجوز لذوي الشأن- وتحديدا المحكوم عليه- خلالها التظلم في الكفالة (مادة 3- 219). هذا التظلم عبارة عن دعوى قضائية ترفع بالإجراءات المعتادة أمام قاضي التنفيذ. وموضوع هذا التظلم هو المنازعة في اختيار كفالة غير منصوص عليها، أو في كفاية ما يودع أو في اقتدار الكفيل أو في أمانة الحارس. أما الصورة الباقية من صور الكفالة، وهي قبول إيداع حصيلة التنفيذ خزانة المحكمة، فلم يدخلها النص كموضوع للتظلم. السبب في ذلك على ما يبدو أنه لا توجد عادة مصلحة في التظلم منها."},{"kind":"text","text":"فإذا تظلم المحكوم عليه في الميعاد، ظل التنفيذ ممتنعا إلى أن يفصل قاضي التنفيذ في التظلم، وهو يفصل فيه بحكم نهائي (مادة 3- 219) لا يقبل الطعن عليه بالاستئناف، ولا بالنقض."},{"kind":"heading","text":"المطلب الثالث: التظلم من وصف الحكم"},{"kind":"text","text":"47- سبق وتأكد لنا أن اعتماد الحكم القضائي كسند تنفيذي يتوقف على توافر عدة شروط، من بينها وصف معين لهذا الحكم، ونقصد بذلك تحديدا أن يكون نهائيا أو مشمولا بالنفاذ المعجل. ولذلك يجب أن تعبر نسخة الحكم بوضوح عن صفته هذه، وإلا اصطدم التنفيذ الجبري بإحدى العقبات التي تعرقل سيره المطرد."},{"kind":"text","text":"فبالنسبة لوصف النهائية، فإنه يستشف بسهولة من كون الحكم صادرا من محكمة استئناف. أما عند صدوره من المحكمة الابتدائية، فالأصل أنه سيكون حكما ابتدائيا وليس نهائيا. وعلى العكس من ذلك، سيكون الحكم نهائيا إذا كان صادرا في النصاب الانتهائي للأحكام الصادرة من الدوائر الابتدائية، أي صادرا في منازعة لا تجاوز قيمتها الخمسين ألف درهم (مادة 1-29-ب)."},{"kind":"text","text":"وعادة لا يتعرض القاضي لوصف حكمه بالابتدائي أو النهائي. ولكن إذا حدث غير ذلك ووصف حكمه، وكان هذا الوصف على غير مقتضى القانون، حق للمتضرر من هذا الوصف الخاطئ أن يطلب تصحيحه."},{"kind":"text","text":"48- وبالنسبة لشمول الحكم بالنفاذ المعجل، فإنه هو الآخر يستشف بسهولة من نص القانون أو من عبارة المنطوق. فالنفاذ المعجل بقوة القانون يستفاد من كون الحكم صادرا في إحدى الحالات المنصوص عليها في المادة 215. كما أن النفاذ المعجل القضائي يستفاد من حكم المحكمة به صراحة."},{"kind":"text","text":"وقد يحدث هنا أيضا خطأ في وصف الحكم. نقابل ذلك في الفرضين الآتيين: 1- أن ينطق القاضي برفض شمول الحكم بالنفاذ المعجل رغم أنه كان واجبا ألا يتعرض للمسألة- رفضا أو استجابة- لأننا أمام حالة من حالات النفاذ المعجل بقوة القانون. 2- أن ينطق القاضي بشمول حكمه بالنفاذ المعجل رغم عدم توافر حالة من حالات النفاذ المعجل القضائي، أو رغم غياب الطلب."},{"kind":"text","text":"بينما لا يعد خطأ في وصف الحكم أن يرفض القاضي شمول الحكم بالنفاذ المعجل القضائي ولو توافرت إحدى حالاته وتم تقديم طلب به. ذلك لأن هذا النفاذ داخل في سلطة المحكمة التقديرية، وبالتالي لا ينسب إليها أي خطأ عند الرفض. كما لا يعد خطأ في وصف الحكم عدم ذكر الأسباب التي بنت عليها المحكمة الحكم بالنفاذ أو برفضه."},{"kind":"text","text":"أخيرا لا يعد خطأ في وصف الحكم تجاهل المحكمة لطلب شمول الحكم بالنفاذ والمقدم في حالة من حالات النفاذ المعجل القانوني. بل إنه حتى لو كان الطلب مقدما بشأن حالة من حالات النفاذ المعجل القضائي، فإن تجاهل المحكمة للطلب يكون مبررا، إذ يمكن اعتباره رفضا ضمنيا له."},{"kind":"text","text":"49- فإذا توافرت حالة من حالات الخطأ في وصف الحكم- سواء من جهة الابتدائية أو النهائية أو الشمول بالنفاذ المعجل- فإن هناك طريقا مخصوصا لتصحيح هذا الخطأ، هو التظلم من وصف الحكم، والذي يسمى أيضا بالاستئناف الوصفي. فالمادة 220 تجيز بالفعل التظلم أمام محكمة الاستئناف من وصف الحكم."},{"kind":"text","text":"ويمكن التعرف على محددات الاستئناف الوصفي من خلال الجوانب الآتية:"},{"kind":"text","text":"فمن ناحية أولى، لا يجوز تصحيح وصف الحكم بالرجوع إلى المحكمة التي أصدرت الحكم. فقاعدة استنفاد المحكمة لولايتها بمجرد إصدارها للحكم يمنع هذا الرجوع، حتى ولو لم يكن هناك طريق آخر مخصوص، فما بالنا وهناك بالفعل هذا الطريق."},{"kind":"text","text":"ومن ناحية ثانية، لولا أن المشرع رسم لتصحيح الوصف طريقا مخصوصا، فإن طريق الطعن بالاستئناف سيكون جائزا. فهو بحكم طبيعته طريق طعن عادي يجوز اللجوء إليه لتصحيح أي نوع من أنواع الخطأ التي يمكن نسبتها إلى الحكم، بما في ذلك وصفه بطبيعة الحال."},{"kind":"text","text":"ومن ناحية ثالثة، فإن الطريق المخصوص الذي رسمه المشرع لتصحيح الخطأ في وصف الحكم هو التظلم (مادة 220). وحقيقة هذا التظلم أنه طعن بالاستئناف بالنظر إلى كونه تصحيح للحكم تختص به محكمة الاستئناف، ويرفع بالإجراءات المعتادة لرفع الاستئناف (مادة 1-220). ولذلك يطلق عليه الاستئناف الوصفي. هذا الاستئناف الوصفي له بعض الخصوصية:"},{"kind":"text","text":"(أ) فهو يرفع إلى محكمة الاستئناف في ميعاد الاستئناف وإلا صار غير مقبول. فبانتهاء هذا الميعاد نكون أمام حكم نهائي في جميع الأحوال ولو كان هناك خطأ في وصفه. ويستثنى من ذلك حالة أن يكون هناك استئناف مرفوع عن الحكم في الميعاد. فعندئذ يجوز إبداء التظلم في الجلسة- ولو بعد فوات ميعاد الاستئناف- أثناء نظر الاستئناف المرفوع عن الحكم (مادة2- 220)."},{"kind":"text","text":"(ب) وتنظر محكمة الاستئناف التظلم أي الاستئناف الوصفي منعقدة في غرفة مشورة (مادة 1-220)، أي دون جلسة يحضرها الخصوم."},{"kind":"text","text":"(ج) ويحكم في التظلم استقلالا (مادة 3- 220). ويقصد بهذه العبارة أنه يجب الحكم في التظلم عقب إبدائه وقبل الفصل في الطعن بالاستئناف المرفوع. ذلك لأنه لن توجد جدوى من نظر التظلم إذا تم الفصل في الاستئناف."},{"kind":"text","text":"(د) والحكم الصادر في التظلم يعتبر حكما صادرا في مسألة وقتية أو مستعجلة، ويخضع الطعن فيه للقواعد الحاكمة لهذا النوع من الأحكام. فهو إذا يقبل الطعن بالنقض."},{"kind":"heading","text":"المطلب الرابع: نظام وقف تنفيذ الحكم القضائي بمناسبة الطعن فيه"},{"kind":"text","text":"50- تبين لنا مما سبق أنه ليس من الضروري أن يكون الحكم القضائي باتا حتى يكون سندا تنفيذيا، وإنما يكفي أن يكون نهائيا، بل ويكفي أن يكون ابتدائيا في بعض الأحوال، أي عندما يكون مشمولا بالنفاذ المعجل القانوني أو القضائي."},{"kind":"text","text":"هذا الوضع معناه أن الحكم القضائي يكون سندا تنفيذيا رغم قابليته للطعن عليه. فالحكم المشمول بالنفاذ المعجل هو حكم ابتدائي وبالتالي قابل للطعن عليه بالاستئناف، كما أن الحكم النهائي قابل للطعن عليه من حيث المبدأ بالنقض (أو التمييز) أو بالتماس إعادة النظر."},{"kind":"text","text":"وهذا معناه أيضا أن النظام القانوني يسمح بتنفيذ جبري قابل للإلغاء. فعندما تنتهي محكمة الطعن إلى إلغاء الحكم المطعون فيه، فإن هذا يستتبع بالضرورة إلغاء التنفيذ الجبري الذي كان قد جرى بناء على الحكم الملغي، أي إعادة الحال إلى ما كان عليه."},{"kind":"text","text":"هذا المصير الذي قد يؤول إليه التنفيذ، لا يخلو من مخاطر. إذ قد تكون إعادة الحال إلى ما كان عليه مستحيلة، وقد تكون ممكنة إلا أنها مرهقة أو مكلفة."},{"kind":"text","text":"51- ولذلك ثارت الحاجة إلى إيجاد وسيلة تسعى إلى إقامة توازن بين مصلحتين متقابلتين ليس من المناسب تغليب إحداهما على الأخرى بصفة مطلقة: الأولى، هي مصلحة الدائن في اتخاذ إجراءات التنفيذ بناء على حكم قضائي، ولو أنه قابل للإلغاء، حتى يحصل على حقه في أقرب وقت. أما الثانية، فهي مصلحة المدين في ألا يصل التنفيذ إلى مرحلته الأخيرة، حتى لا يضطر إلى إعادة الحال إلى ما كان عليه، وما يحمله ذلك من مخاطر، تلك المخاطر التي توجد عادة إذا اكتمل التنفيذ وتنتفي عند عدم اكتماله."},{"kind":"text","text":"ولقد وجد النظام القانوني ضالته المنشودة للتوفيق بين المصلحتين السابقتين، في نظام \"وقف التنفيذ\" الذي يمكن الحكم به من محكمة الطعن. فقد أجازت المادة 221 طلب وقف التنفيذ من محكمة الطعن بالاستئناف عندما يكون الحكم سند التنفيذ مشمولا بالنفاذ المعجل، كما أجازت المادتان 2- 174 و2- 177 تقديم هذا الطلب إلى محكمة الطعن بالالتماس أو النقض- بحسب الأحوال- وذلك عندما يكون الحكم سند التنفيذ نهائيا."},{"kind":"text","text":"ونظرا لأن طلب الوقف المقدم لمحكمة الطعن هو طلب قضائي بمعنى الكلمة، سيكون من الطبيعي أن نتناول شروط قبوله في فرع أول. ونظرا لاعتداء الوقف على القوة التنفيذية للحكم القضائي، كان من الطبيعي أن يحدد النظام القانوني شروطا للاستجابة لطلب الوقف. لذلك يجب أن نتناول في فرع ثان شروط الحكم بالوقف. وسوف نتناول في فرع ثالث النظام الإجرائي لطلب الوقف."},{"kind":"text","text":"الفرع الأول: شروط قبول طلب الوقف"},{"kind":"text","text":"52- يقصد بقبول الطلب- أي طلب- مجرد صلاحيته للنظر فيه. ويتبين من النصوص، ومن النظرية العامة للطلب القضائي- خاصة المستعجل أو الوقتي وهو ما ينطبق على طلب الوقف - أنه يجب لقبوله إذا ما قدم لمحكمة الطعن، توافر الشرطين الآتيين:"},{"kind":"text","text":"الشرط الأول: تقديم طلب الوقف بالتبعية للطعن"},{"kind":"text","text":"53- إذا استعرضنا النصوص التي تنظم طلب وقف التنفيذ من محاكم الطعن، فإننا نلحظ بسهولة أن الشرط الأول لطلب وقف التنفيذ من محكمة الطعن هو أن يقدم هذا الطلب بالتبعية للطعن، أي أن تكون سلطة المحكمة في نظر هذا الطلب مقيدة بكونه طلبا مقرونا بالطعن بالفعل في الحكم المطلوب وقف تنفيذه. فبالنسبة لطلب الوقف المقدم في الاستئناف، تقطع المادة 221 بضرورة هذا الشرط، فهي تتكلم عن طلب الوقف المقدم إلى \"المحكمة المرفوع إليها الاستئناف\". أما بالنسبة لطلب الوقف المقدم في مرحلة النقض أو التمييز، فإن المادة 2-177 تقطع هي الأخرى بذلك، فهي تتكلم عن جواز وقف التنفيذ من محكمة الطعن بالنقض \"إذا طلب الطاعن ذلك في صحيفة الطعن\"."},{"kind":"text","text":"وبناء عليه، لا يجوز التقدم إلى محاكم الطعن بطلب مستقل لوقف التنفيذ، أي لوقف تنفيذ حكم غير مطعون عليه. أيضا لن يكون الطلب مقبولا عندما تكون صحة الطعن أو قبوله محل نزاع جدي. وإذا تعدد المحكوم عليهم، لا يجوز طلب الوقف ممن لم يطعن منهم على الحكم."},{"kind":"text","text":"هذا التعاصر الزماني لطلب الوقف والطعن على هذا النحو، يعد كافيا لتحقق شرط التبعية عندما يكون طلب الوقف مقدما إلى محكمة الطعن بالاستئناف أو الالتماس. وبناء عليه، يجوز تقديم طلب الوقف في صحيفة الطعن بالاستئناف مثلا، كما يجوز تقديم هذه الصحيفة خالية من هذا الطلب ثم تقديمه في وقت لاحق كطلب عارض، فالمهم أنه وقت تقديم طلب الوقف، يوجد طعن مرفوع بالفعل."},{"kind":"text","text":"54- ولكن عندما يكون طلب الوقف مقدما إلى محكمة الطعن بالنقض (أو التمييز)، فإنه لا يكفي هذا التعاصر الزماني، وإنما يجب أن يتوافر معه أيضا التعاصر المادي. فحتى يتحقق شرط التبعية هنا، يجب أن يقدم طلب الوقف في ذات صحيفة الطعن (مادة 2-177). وعندئذ لن يكون الطلب مقبولا إذا قدم في صحيفة مستقلة في وقت لاحق على رفع الطعن. ولعل العلة من هذا التشدد هي الحد من طلبات الوقف التي تستهدف النيل- ولو مؤقتا- من القوة التنفيذية لحكم نهائي، أي لحكم حائز للقوة التنفيذية وفقا للقاعدة العامة وليس الاستثنائية."},{"kind":"text","text":"الشرط الثاني: عدم تمام التنفيذ"},{"kind":"text","text":"55- لا شك أن طلب وقف التنفيذ المقدم إلى محكمة الطعن هو ممارسة لحق الدعوى، ولذلك يشترط لقبوله الشروط العامة لقبول الدعاوى. ولعل من أبرز هذه الشروط، شرط المصلحة بأوصافها المتعددة. هذا الشرط يعبر عنه في خصوص طلب وقف التنفيذ- وأيا كان القضاء المقدم له هذا الطلب- بصياغة معينة، هي ألا يكون التنفيذ قد اكتمل. إذ لن يكون للحكم الصادر بوقف التنفيذ- على فرض صدوره- أية فائدة عملية إذا كان التنفيذ قد اكتمل فعلا قبل طلب استصداره أو حتى قبل صدوره."},{"kind":"heading","text":"56- من المهم إذا تحديد المقصود بتمام التنفيذ الذي يحول دون قبول طلب الوقف."},{"kind":"text","text":"وأول ما يلاحظ في هذا الصدد، أنه إذا كان التنفيذ مباشرا، فإنه يتكون عادة من مرحلة وحيدة، بحيث يكتمل عادة عقب البدء فيه مباشرة. نقابل ذلك في حالة تنفيذ الحكم الصادر مثلا بتسليم عقار أو منقول أو غلق محل تجاري. وهنا يبدو واضحا القول بأنه يجب تقديم الطلب قبل البدء في التنفيذ."},{"kind":"text","text":"57- أما إذا كان التنفيذ يجرى بطريق الحجز، فإنه يمر بمراحل متعاقبة يستغرق كل منها وقتا. فهو يبدأ بمرحلة الحجز ثم البيع ثم توزيع حصيلة التنفيذ. ولذلك يجب تقديم طلب الوقف قبل انتهاء هذه المرحلة الأخيرة حتى يكون مقبولا. أما إذا قدم الطلب إلى محكمة الطعن قبل انتهاء مرحلته الأخيرة هذه، إلا أن التنفيذ ظل مستمرا - وهذا طبيعي- واكتمل قبل الجلسة المحددة لنظره، فالأصل أن محكمة الطعن لا تملك حينئذ سوى الحكم بعدم قبول الطلب لانقضاء المصلحة."},{"kind":"text","text":"58- ولكن يرد على هذا الأصل استثناء يتمثل في طلب الوقف المقدم لمحكمة الطعن بالنقض. فاكتمال التنفيذ في وقت لاحق على تقديم الطلب إلى هذه المحكمة، لا يحول دون قبوله والحكم بوقف التنفيذ. والدليل على إقرار المشرع لهذا الاستثناء هو نص المادة 5-177 حين قررت أنه\".. ينسحب الأمر الصادر بوقف تنفيذ الحكم على إجراءات التنفيذ التي اتخذها المحكوم له بناء على الحكم المطعون فيه من تاريخ تقديم الطلب\". فهذا النص وما يقرره من أثر رجعي للحكم الصادر بالوقف من محكمة الطعن بالنقض يفيد أن طلب الوقف يكون مقبولا رغم تمام التنفيذ اللاحق على تقديمه، كما يفيد أيضا جواز الحكم بوقف التنفيذ بعد ذلك. وعليه، فإنه إذا لم يكن التنفيذ قد بدأ وقت تقديم طلب الوقف إلى محكمة الطعن بالنقض، إلا أنه قد وقع حجز بعد تقديمه وأعقب ذلك بيع، فإن تمام التنفيذ هنا لا يمنع من قبول الطلب ولا من الحكم بالوقف ولا من انسحاب هذا الحكم على إجراءات التنفيذ التي سبق اتخاذها، واعتبارها كأن لم تكن."},{"kind":"text","text":"الفرع الثاني: شروط الحكم بوقف التنفيذ"},{"kind":"text","text":"59- الفرض الآن أن طلب وقف التنفيذ المقدم لمحكمة الطعن صالح للنظر فيه، أي مقبول شكلا، ولذلك يجب التساؤل عن الشروط المطلوبة لكي يصدر في موضوع هذا الطلب إما حكم بوقف التنفيذ وإما برفضه إذا ما تخلفت هذه الشروط أو حتى تخلف واحد منها."},{"kind":"text","text":"وقد توافقت النصوص المنظمة للطلب محل البحث على شرطين للحكم بالوقف، هما ضرورة توافر الخشية من وقوع ضرر غير عادي من التنفيذ، وتمتع محكمة الطعن بسلطة جوازية."},{"kind":"text","text":"الشرط الأول: الخشية من وقوع ضرر غير عادي من التنفيذ"},{"kind":"text","text":"60- تعبر المادة 1- 221 عن هذه الخشية وعن هذا الضرر بمناسبة طلب وقف التنفيذ المقدم لمحكمة الاستئناف بقولها \"إذا كان يخشى وقوع ضرر جسيم من التنفيذ\". وتزيد المادة 1- 177 من درجة التشدد المطلوبة في الضرر للحكم بالوقف من محكمة الطعن بالنقض، بقولها\" وكان يخشى أن يؤدي التنفيذ إلى وقوع ضرر جسيم يتعذر تداركه\". وهي أيضا نفس درجة التشدد التي تطلبتها المادة 1- 174 بمناسبة طلب الوقف المقدم لمحكمة الطعن بالالتماس."},{"kind":"text","text":"فالمعروف أن كل تنفيذ يرتب أضرارا للمنفذ ضده، فهو يتضمن بالتأكيد مساسا بحقوق المنفذ ضده على أمواله. ولذلك فإنه حتى لو تمت ممارسته على النحو المعتاد، فإنه يكون دائما عملا ضارا بالنسبة له، وليس عملا نافعا ولا حتى دائرا بين النفع والضرر. ويعبر عن ذلك بأن الحق في التنفيذ من حقوق الإضرار بطبيعتها، هذا الضرر الذي يصيب المنفذ ضده يجب تحمله في معظم الأحيان، كما يمكن إزالته أيضا إذا لزم الأمر. ولذلك فإن هذا الضرر \"العادي\" لا يبرر الحكم بوقف التنفيذ من محكمة الطعن، نظرا لتوافره دائما في كل طلب يقدم لوقف التنفيذ، وإلا أمكن للمنفذ ضده تعطيل التنفيذ بإرادته المنفردة. بعكس الحال لو كان هذا الضرر \"غير عادي\". ولذلك كان المشرع منطقيا عندما تطلب للحكم بالوقف من جانب محكمة الاستئناف، أن يكون الضرر الذي سيترتب على التنفيذ \"ضررا جسيما\". وكان أكثر منطقية حين تشدد أكثر وتطلب \"ضررا جسيما يتعذر تداركه\" للحكم بالوقف من جانب محكمة الطعن بالنقض أو بالالتماس."},{"kind":"text","text":"وتحديد درجة الضرر وما إذا كان يعد جسيما، إنما هو مسألة تقديرية تختلف باختلاف الظروف الشخصية والموضوعية. فبالنظر إلى الظروف الشخصية، فإن الضرر الذي يصيب شخصا معينا قد يكون بسيطا، ويعتبر هو ذاته جسيما إذا أصاب شخصا آخر. وبالنظر إلى الظروف الموضوعية أو الاقتصادية، فإن ما يعد ضررا عاديا في زمن معين قد يعد ضررا جسيما في زمن آخر."},{"kind":"text","text":"وكذلك تعذر تدارك الضرر، فهو أيضا مسألة تقديرية. وهو يتوافر عندما يكون الضرر المتوقع نتيجة التنفيذ من المستحيل إصلاحه لا عينا ولا بمقابل، أو كان ممكنا إصلاحه ولكن بصعوبة ورهق، بأن كان يقتضي وقتا طويلا أو مصاريف باهظة. والحكمة من تشدد المشرع حين اشترط تعذر تدارك الضرر ولم يكتف بكونه جسيما حين يكون طلب الوقف مقدما إلى محكمة النقض أو الالتماس، هي أن الحكم المطلوب وقف تنفيذه هنا هو حكم نهائي، فكان من المنطق التضييق من احتمالات تعطيل قوته التنفيذية، مقارنة بالحكم المشمول بالنفاذ المعجل- وهو حكم ابتدائي- والمطلوب وقف تنفيذه من محكمة الاستئناف."},{"kind":"text","text":"الشرط الثاني: السلطة التقديرية للحكم بالوقف، وشرط ترجح الإلغاء"},{"kind":"text","text":"61- لا يكفي أن يتوافر الضرر الجسيم أو حتى الذي يتعذر تداركه، لكي تكون محكمة الطعن ملزمة بالحكم بوقف التنفيذ. فقد أعطتها النصوص سلطة جوازية للحكم بالوقف عند توافر هذا الضرر، ولم تفرض عليها الحكم به. السبب في ذلك في رأينا أن الضرر حتى غير العادي يظل مع ذلك ضررا \"قانونيا\"، بمعنى أن سببه مشروع، وهو الحق في التنفيذ. ولكن حتى يمكن لمحكمة الطعن أن تقرر رغم ذلك الحكم بالوقف، يحسن أن يكون لديها ما يرجح وجود مبرر للوقف. ولذلك أراد المشرع أن يجعل زمام الأمر بيدها، لعلها تجد هذا المبرر في ترجح إلغاء الحكم المطلوب وقف تنفيذه. فرغم أن المواد المنظمة لوقف التنفيذ بواسطة محاكم الطعن لم تتضمن صراحة شرط ضرورة أن تكون أسباب الطعن في الحكم يرجح معها إلغاؤه، إلا أنه ليس معنى ذلك أنه شرط غير مطلوب. فالواقع أنه شرط تفرضه قواعد الحماية الوقتية والتي ينتمي إليها الطلب محل البحث. كل ما هنالك أن المشرع لجأ إلى صياغة تسمح لمحكمة الطعن أن تأخذ هذا الشرط في الاعتبار دون أن تترك لدى المتقاضين الاعتقاد بأنه إذا حكمت بوقف التنفيذ فإنه قد استبان لها ضرورة إلغاء الحكم. فإدخال شرط ترجح الإلغاء تحت ستار السلطة الجوازية للحكم بالوقف، يحفظ سلطة المحكمة الكاملة في رفض الطعن في وقت لاحق، حتى ولو سبق لها الحكم بالوقف."},{"kind":"text","text":"الفرع الثالث: النظام الإجرائي لطلب الوقف"},{"kind":"heading","text":"62- يقصد بذلك إجراءات الحصول على حكم في طلب الوقف، والطعن في هذا الحكم، وتنفيذه."},{"kind":"text","text":"أولا: طريقة تقديم طلب الوقف"},{"kind":"text","text":"63- نص المشرع على طريقة تقديم طلب الوقف إلى محكمة الطعن بالنقض (أو التمييز). فالطلب هنا لن يكون مقبولا إلا إذا كان مذكورا في صحيفة الطعن. ولذلك فإن طريقة تقديمه هي ذاتها طريقة تقديم هذه الصحيفة، وهي إيداعها لدى مكتب إدارة الدعوى، بالإجراءات المقررة، متضمنة طلب وقف التنفيذ."},{"kind":"text","text":"بينما لم ينص المشرع على طريقة تقديم طلب الوقف إلى محكمة الطعن بالاستئناف أو الالتماس. لذلك سوف تنطبق عندئذ القواعد العامة، والتي تسمح بأن تتضمنه صحيفة الطعن، والتي تقدم بإيداعها مكتب إدارة الدعوى، كما تسمح هذه القواعد أيضا بإبداء طلب الوقف في وقت لاحق، بنفس طريقة إبداء الطلبات العارضة."},{"kind":"text","text":"ثانيا: الحكم الصادر في طلب الوقف"},{"kind":"text","text":"64- القرار الصادر في طلب الوقف المقدم لمحكمة الطعن ليس \"أمرا\" لعدم صدوره وفقا للنظام الإجرائي للأوامر القضائية. وإنما هو حكم قضائي بكل معنى الكلمة، فهو يصدر في منازعة، مرفوعة من خلال النظام القانوني للخصومة القضائية. ولذلك يجب أن يصدر الحكم الصادر في طلب الوقف في الشكل الذي تصدر فيه الأحكام، وتحكمه عموما النصوص الواردة في باب الأحكام"},{"kind":"text","text":"وهو حكم وقتي أو مستعجل، لأنه لا يتضمن فصلا في أصل الحق في التنفيذ ولا في موضوع الطعن، وإنما فقط في إجراء وقتي هو وقف التنفيذ مؤقتا لحين الفصل في الطعن. وتترتب على الصفة المستعجلة للحكم الصادر في طلب الوقف عدة نتائج: أهمها، أنه سيقبل الطعن المباشر رغم كونه حكما صادرا أثناء خصومة الطعن ولا تنتهي به الخصومة كلها. تظهر قيمة ذلك فقط بالنسبة للحكم الصادر في طلب الوقف المقدم إلى محكمة الاستئناف أو الالتماس. أما الحكم الصادر من محكمة النقض فهو لا يقبل الطعن عليه بأي طريق."},{"kind":"text","text":"وكونه حكما مستعجلا لا يمنع من خضوعه لما تخضع له سائر الأحكام من شرائط المداولة والتسبيب وغير ذلك مما نص عليه في باب الأحكام."},{"kind":"text","text":"ثم إنه حكم قطعي، ويستنفد بالتالي ولاية المحكمة."},{"kind":"text","text":"ثالثا: تنفيذ الحكم"},{"kind":"text","text":"65- إذا كان الحكم في طلب الوقف صادرا برفضه أو بعدم قبوله، فإنه يعتبر حكما مقررا لا يحتاج إلى تنفيذ جبري. وحتى عندما يكون صادرا بوقف التنفيذ، فإنه وإن تضمن إلزاما موجها إلى الدائن بالكف عن التنفيذ، إلا أنه إلزام لا يحتاج إلى تنفيذ جبري، نظرا لكونه لا يحتاج إلى تدخل من جانب المحكوم عليه. إذ يكفي المحكوم له التقدم بصورة مصدقة من نسخة الحكم- وليس صورة تنفيذية- إلى قاضي التنفيذ لكي يمتنع عن الاستمرار في التنفيذ."},{"kind":"text","text":"على أن الحال يختلف إذا كان حكم الوقف صادرا من محكمة الطعن بالنقض. فقد يتضمن هذا الحكم إلزاما بإعادة الحال إلى ما كان عليه وقت تقديم الطلب. فإذا كان التنفيذ قد اكتمل، بأن تم توزيع حصيلة التنفيذ أو تم إخراج شاغل العقار منه أو تم تسليم المنقول، فعندئذ- وعندئذ فقط- سيكون حكم وقف التنفيذ في حاجة إلى تنفيذ جبري بمعنى الكلمة لإعادة الحال إلى ما كان عليه. ولذلك يجب في هذه الحالة الحصول على صورة تنفيذية من حكم الوقف حتى يمكن إجراء التنفيذ العكسي."},{"kind":"text","text":"رابعا: الطعن في الحكم"},{"kind":"text","text":"66- نبادر ونحسم المسألة بالنسبة للحكم الصادر في طلب وقف التنفيذ من محكمة الطعن بالنقض أو التمييز. فالمادة 177 تقطع الطريق أمام أية محاولة للبحث في هذا الصدد، حيث تنص على أنه “لا يجوز الطعن في أحكام النقض بأي طريق من طرق الطعن..\"."},{"kind":"text","text":"أما الحكم الصادر في طلب الوقف من محكمة الاستئناف، فإنه يقبل الطعن بالنقض، لكونه حكما صادرا في طلب غير مقدر القيمة وبالتالي في طلب تزيد قيمته على خمسمائة ألف درهم، ومن ثم تتوافر فيه شروط الحكم القابل للطعن بهذا الطريق. والطعن بالنقض هنا هو طعن فوري أو مباشر كما سبق ورأينا."},{"kind":"text","text":"أيضا يجوز الطعن بالنقض في الحكم الصادر في طلب الوقف المقدم إلى المحكمة التي تنظر الطعن بالتماس إعادة النظر، إذا كانت هذه الأخيرة محكمة استئناف."},{"kind":"heading","text":"المبحث الثاني: الأوامر القضائية"},{"kind":"text","text":"67- ذكرت المادة 2-212-أ \"الأوامر\" عند تعدادها للسندات التنفيذية، وهي تقصد بذلك كلا من الأوامر على عرائض المنصوص عليها في المواد 140 إلى 142، وأوامر الأداء المنصوص عليها في المواد من 143 إلى 150."},{"kind":"text","text":"ونظرا للتزايد المضطرد لاستعمال أوامر الأداء في الواقع العملي، فسوف نتناولها أولا في مطلب أول، ثم نتناول الأوامر على عرائض في مطلب ثان."},{"kind":"heading","text":"المطلب الأول: أوامر الأداء"},{"kind":"text","text":"تقسيم"},{"kind":"text","text":"68- سوف نتعرف في فرع أول على المقصود بأمر الأداء وأهميته ومدى إلزامية سلوك طريقه، ثم نتعرف في فرع ثان على شروط الحق الذي يمكن المطالبة به من خلال نظام أوامر الأداء، أما الفرع الثالث فسوف ينشغل بتحديد القاضي المختص بأوامر الأداء، بينما ينشغل الفرع الرابع بإجراءات طلب أمر الأداء، أما الفرع الخامس فسوف يستعرض الصيغ المختلفة التي يظهر بها أمر الأداء، وأما الفرع السادس فهو عن طرق مراجعة الأمر، وأما الفرع السابع والأخير فهو عن تنفيذ أمر الأداء."},{"kind":"text","text":"الفرع الأول: ماهية أوامر الأداء وأهميتها ومدى إلزاميتها"},{"kind":"text","text":"ماهيتها وأهميتها"},{"kind":"text","text":"69- أمر الأداء هو ما يصدر من القاضي المختص عند المطالبة بحق من الحقوق التي تتوافر فيه شروط معينة (هي الثبوت والكتابة وتعيين المقدار وحلول الأداء)، قدر المشرع عدم الحاجة بصدده إلى اتباع القواعد العامة في الدعوى وما يعقبها من خصومة، وإنما إجراءات أخرى مخصوصة تغيب عنها-ولو مرحليا- فكرة المواجهة."},{"kind":"text","text":"هذا الأمر يعتبر من السندات التنفيذية بصريح نص المادة 2-212-أ."},{"kind":"text","text":"ومن الناحية العملية، تعتبر أوامر الأداء مزاحما واضحا للأحكام القضائية كسندات تنفيذية. ويرجع ذلك في المقام الأول إلى التنظيم القانوني لهذه الأوامر، والذي جعلها تتمتع بجملة خصائص وتتحقق من ورائها فوائد متعددة."},{"kind":"text","text":"فأبرز ما يميز أوامر الأداء أنها أولا سندات قضائية. فأمر الأداء هو \"أمر قضائي\" له ما للأحكام القضائية من حجية، نظرا لأنه- وكما سنرى لاحقا في شروط المطالبة التي تسمح بسلوك طريق الأداء- يقطع بثبوت حق الدائن الموضوعي، ويزكي بالتالي إعطاءه الحق في التنفيذ الجبري. وثانيا، أنها نموذج يحتذى للعدالة الناجزة، حيث يمكن الحصول على أمر الأداء من خلال إجراءات مبسطة ووقت قصير، ودون حاجة إلى رفع الدعوى بالطريقة المعتادة وما يستتبع ذلك من جلسات وما تستغرقه من وقت. وأخيرا، أنها نموذج أيضا للحصول على حماية. تنفيذية سريعة، حيث تسري عليها القواعد الخاصة بالنفاذ المعجل، كما يمكن التوصل إلى نهائيتها في وقت قصير."},{"kind":"text","text":"مدى إلزامية سلوك طريق أمر الأداء"},{"kind":"text","text":"70- رسم المشرع طريقا معينا، يمكن تسميته بطريق أمر الأداء، للمطالبة ببعض الحقوق. وهو طريق إجرائي يختلف عن الطريق المعتاد، أي طريق الدعوى القضائية. ومفاد ذلك بحسب الأصل، أنه يجب على من تتوافر في حقه شروط طريق أمر الأداء أن يسلك هذا الطريق، وأنه يجب على المحكمة التي ترفع إليها دعوى تتضمن مطالبة تتوافر فيها شروط استصدار أمر الأداء، أن تحكم بعدم قبول الدعوى لعدم سلوك الطريق الذي رسمه القانون."},{"kind":"text","text":"ومع ذلك خفف المشرع كثيرا من حدة النتائج التي تترتب على هذا الأصل، للدرجة التي يمكن معها القول بأنه خرج عليها كلية:"},{"kind":"text","text":"(أ) فمن ناحية أولى، الأصل أن على القاضي المشرف على مكتب إدارة الدعوى تحضير المطالبة التي ترفع بها الدعوى القضائية بحالتها. ولكن خرج المشرع على هذا الأصل وأعطى للقاضي المشرف دورا استثنائيا تجاه الدائن الذي لجأ إلى الطريقة المعتادة لرفع الدعوى رغم توافر شروط استصدار أمر الأداء في مطالبته. إذ للقاضي المشرف هنا أن ينزل التكييف الصحيح على المطالبة، وأنها طلب أمر أداء بصرف النظر عن طريقة تقديمه. وبعدها يقوم بإحالتها إلى قاضي أمر الأداء المختص (المادة 9- 45)، أو يقوم هو بإصدار أمر أداء فيها إن كان مختصا بذلك."},{"kind":"text","text":"(ب) ومن ناحية ثانية، أنه إذا فات على القاضي المشرف في الفرض السابق القيام بالتكييف الصحيح، وقام بتحضير المطالبة على أنها دعوى، وأحالها بالتالي إلى المحكمة لتنظر فيها وفقا للطريق المعتاد لنظر الدعاوى، فالمفروض أن يؤدي توافر شروط استصدار أمر الأداء في هذه الدعوى إلى الحكم بعدم قبولها. ومع ذلك، كان للمشرع رأي مخالف. فقد أوجب على المحكمة نظر الدعوى وإصدار \"حكم\" فيها وفقا للقواعد المقررة للفصل في الدعاوى (مادة 150)."},{"kind":"text","text":"واضح من الفرضين السابقين، أن سلوك طريق أمر الأداء لم يعد وجوبيا."},{"kind":"text","text":"(ج) ومن ناحية ثالثة، فإنه إذا سلك الدائن طريق أمر الأداء رغم عدم توافر شروطه، فليس للقاضي المشرف إنزال التكييف القانوني الصحيح واعتبار المطالبة بمثابة دعوى قضائية، إذ لم تعطه النصوص هذه السلطة في هذا الفرض. لذلك ليس أمامه سوى إحالة المطالبة إلى قاضي الأداء المختص لكي يصدر هو فيها أمرا بعدم القبول."},{"kind":"text","text":"(د) ولكن ما هو الحل الواجب الاتباع في الفرض الذي ترفع فيه دعوى بالإجراءات المعتادة، وتكون منطوية على طلبين أحدهما هو المطالبة بحق توافرت فيه الشروط المطلوبة لسلوك طريق الأداء والآخر ليس كذلك؟"},{"kind":"text","text":"أرى أنه يجب على القاضي المشرف أن يقوم في هذا الفرض بتحضير الدعوى كالمعتاد، ثم إحالتها إلى هيئة الحكم. فوجود طلب لا يصلح لسلوك طريق الأداء سيجعل الدعوى مقبولة بالنسبة للحقين معا وذلك وفقا لنظرية الارتباط."},{"kind":"text","text":"أما إذا لم يوجد أي ارتباط بين الطلبين، فعلى القاضي المشرف أن يعطي التكييف الصحيح لكل منهما، فيقوم بتحضير الطلب الأول وإحالته إلى هيئة الحكم في الدعوى، وإحالة الطلب الثاني- بعد إعادة تكييفه- إلى قاضي الأداء المختص."},{"kind":"text","text":"(ه) إذا رفعت دعوى بالإجراءات المعتادة، وأثناء نظرها قدم إلى المحكمة طلب عارض مما تتوافر فيه شروط اللجوء إلى طريق أمر الأداء، اعتبر هذا الطلب العارض داخلا في اختصاصها ومقبولا. فسلوك طريق الأداء في هذا الفرض ليس واجبا إذا كانت الدعوى فرعية. فقد سبق ورأينا أنه حتى من يقدم طلبه بطريق الدعوى الأصلية رغم توافر مفترضات سلوك طريق الأداء ولم يتنبه القاضي المشرف لذلك، فإن دعواه تكون مقبولة."},{"kind":"text","text":"الفرع الثاني: شروط الحق موضوع المطالبة"},{"kind":"text","text":"71- خص المشرع أوامر الأداء بنوع من المطالبات التي رأى أنها لا تستأهل انعقاد الخصومة بشأنها وما يستتبعه ذلك من وجاهية وتحقيق كامل. فقد اصطفى المشرع مطالبات ثابتة، ومن الأرجح ألا يكون للمدين فيها ما يعارض به ادعاء الدائن."},{"kind":"text","text":"فالمطالبة التي تصلح لاستصدار أمر الأداء ليست أي مطالبة، وإنما فقط المطالبة بحق مستجمع للشروط الثلاثة التي عددتها المادة 1- 143. هذه الشروط هي:"},{"kind":"text","text":"72- الشرط الأول: أن يكون الحق المطالب به ثابتا بالكتابة. يستوي في ذلك أن تكون الكتابة الكترونية أو مستندية (ورقية)، رسمية أو عرفية."},{"kind":"text","text":"والكتابة المفصحة في ذاتها على أن المطلوب استصدار أمر الأداء ضده هو الموقع على الورقة ويلتزم دون غيره بأداء الدين وقت استحقاقه، ليست فقط مطلوبة لإثبات الحق المطالب به، وإنما أيضا لإثبات باقي شروط هذا الحق- والتي سنتعرف عليها حالا- وتبرر سلوك طريق أوامر الأداء. فيجب أن يكون تعيين المقدار ثابتا بالكتابة، كما يجب أن يكون محل الحق المطالب به ثابتا أيضا بالكتابة."},{"kind":"text","text":"وقد يكون الحق المطالب به ثابتا بالكتابة، ولكنه كان في ذات الوقت معلقا على شرط واقف أو على قيام الدائن بالوفاء بالتزام مقابل. هذا الحق يصلح لاستصدار أمر أداء طالما أنه ثابت بالكتابة، إذ لم يشترط النص في الحق أن يكون محقق الوجود. إلا أن الدائن لن يستطيع وضع هذا الأمر موضع التنفيذ الجبري إلا إذا كان قد أثبت لقاضي الأداء- وكتابة- تحقق الشرط أو الوفاء بالالتزام المقابل."},{"kind":"heading","text":"73- الشرط الثاني: أن يكون الحق حال الأداء"},{"kind":"text","text":"وهذا الشرط منطقي، وذلك لأنه لا تجوز المطالبة القضائية- وهو وصف ينطبق حتى على المطالبة من خلال نظام أمر الأداء- إلا إذا كان الدين حال الأداء. فإذا كان الدين مضافا إلى أجل، فيجب أن يكون أجله قد حل بالفعل."},{"kind":"heading","text":"74- الشرط الثالث: أن يكون محل الحق المطالب به دينا من النقود معين المقدار أو منقولا معينا بذاته أو بنوعه ومقداره."},{"kind":"text","text":"فعندما يكون الحق المطالب به دينا من النقود، فيجب أن يكون مقداره رقما محددا أو ممكنا تحديده بعملية حسابية بسيطة، أو بناء على أسس ثابتة لا يكون معها للقضاء سلطة رحبة في التقدير."},{"kind":"text","text":"وأما عندما يكون محل الحق المطالب به منقولا، فيستوي أن يكون من القيميات، ومثاله سيارة تحمل رقما مروريا معينا، أو من المثليات المعين نوعها ومقدارها، ومثاله كمية معينة من الأرز البسمتي."},{"kind":"text","text":"ويجب أن يكون كل ما سبق ثابتا بالكتابة. كما أنه من الواضح استبعاد العقار من مجال أوامر الأداء."},{"kind":"text","text":"75- والسؤال الآن هو الآتي: هل ما ذكره البند (2) من المادة 143 من وجوب سلوك نظام أمر الأداء إذا \"كان صاحب الحق دائنا بورقة تجارية باستثناء الشيك..\"، كالسند لأمر مثلا، اعتبار هذه المطالبة صالحة بحكم القانون لاستصدار أمر أداء بصرف النظر عن توافر الشروط الثلاثة المذكورة أنفا؟"},{"kind":"text","text":"الحقيقة أن البند المذكور لم يستهدف سوى لفت النظر إلى صلاحية المطالبة التي محلها ورقة تجارية لاستصدار أمر أداء، ولكن دون التخلي عن ضرورة توافر الشروط العامة السابق ذكرها. ولذلك قد يكون الحق الثابت في السند لأمر غير حال الأداء، وعندئذ لن يكون مقبولا طلب استصدار أمر الأداء."},{"kind":"heading","text":"76- وهل المطالبة المالية التي محلها إنفاذ عقد تجاري لا تصلح لكي تكون محلا لطلب أمر أداء؟"},{"kind":"text","text":"السبب في طرح هذا التساؤل هو أن البند (2) من المادة 143 لم يذكر وجوب سلوك أمر الأداء \"إذا كانت المطالبة المالية محلها إنفاذ عقد تجاري\" على خلاف ما كان مقررا من قبل. على أنه ليس معنى ذلك استبعاد هذه المطالبة من مجال أوامر الأداء. فطالما توافرت فيها الشروط الثلاثة السابق ذكرها وجب اللجوء إلى نظام أوامر الأداء. لا يوجد ما يمنع إذا من استصدار أمر أداء بتنفيذ عقد تجاري ثابت بالكتابة، والدين فيه حال الأداء ومعين المقدار، أو الالتزام المتولد عنه هو تسليم بضاعة مثلا أو دفع ثمنها."},{"kind":"text","text":"77- نصل الآن إلى ما ورد في أول عبارة البند (3) من المادة 143 والتي تقرر أنه \" لا يمنع من سلوك أمر الأداء طلب الفوائد أو التعويض\". والقصد من هذا النص التأكيد على أن جواز سلوك أمر الأداء ليس فقط لطلب أصل الحق وإنما أيضا لطلب توابع ذلك من الفوائد أو التعويضات. على أنه يجب دائما وأبدا أن تتوافر في أي من هذه المطالب الشروط الثلاثة السابقة. ينطبق ذلك مثلا على المطالبة بالتعويض الاتفاقي المحدد في العقد المكتوب والذي يستند إليه الدائن في المطالبة. كما ينطبق أيضا على طلب الفوائد التي يمكن تحديد مقدارها بعملية حسابية بسيطة. فإذا لم تتوافر الشروط في التعويضات أو الفوائد، فلا يجوز طلبها من خلال سلوك أمر الأداء. وفي نفس الوقت لن يكون هذا مبررا لرفع دعوى قضائية بها وكذلك بأصل الحق. فسلوك طريق أمر الأداء يظل هو الواجب الاتباع تجاه أصل الحق، طالما توافرت فيه الشروط المطلوبة.."},{"kind":"text","text":"78- أما ما ورد في آخر عبارة البند (3) من المادة 143 من أنه \"لا يمنع من سلوك أمر الأداء طلب.. اتخاذ أي إجراء من الإجراءات التحفظية\"، فيقصد بها أساسا عقد اختصاص لقاضي الأداء بإصدار أمر بتوقيع حجز تحفظي أو منع المدين من السفر، متى طلب ذلك منه مع عريضة أمر الأداء. والذي يؤكد هذا المعنى هو ما ورد في البند (5) من المادة 147 والتي تشير إلى خضوع “الإجراءات التحفظية الصادرة مع الأمر\" لطرق المراجعة التي يخضع لها الأمر ذاته. أما إذا لم يقدم الدائن هذه العريضة، فليس له أن يطلب- استقلالا- من قاضي الأداء، الحجز التحفظي أو غيره من الإجراءات التحفظية، حتى ولو كان دينه مما تتوافر فيه الشروط التي تجعل سلوك أمر الأداء إلزاميا."},{"kind":"text","text":"الفرع الثالث: القاضي المختص بأوامر الأداء"},{"kind":"text","text":"79- لم تنشغل النصوص المنظمة لأمر الأداء إلا بالاختصاص ا المحلي لقاضي الأداء، وقد ركزته المادة 1- 144 في “قاضي المحكمة التي يقع في دائرتها موطن المدين أو المحكمة التي تم الاتفاق أو نفذ كله أو بعضه في دائرتها أو المحكمة التي كان يجب تنفيذ الاتفاق في دائرتها..\". الواضح من هذا النص انصراف إرادة المشرع الصريحة إلى إخضاع الاختصاص المحلي لقاضي الأداء لقاعدة خاصة. ومفاد ذلك ولازمه عدم سريان باقي قواعد الاختصاص المحلي المعروفة حتى ولو توافر مقتضاها."},{"kind":"text","text":"80- أما عن الاختصاص النوعي، فإنه- ونظرا لعدم وجود نص- ينعقد بطبيعة الحال للدائرة الابتدائية والتي تجعلها المادتان 24و29 هي المختصة من حيث المبدأ بكافة الطلبات والدعاوى."},{"kind":"text","text":"وقد يكون القاضي المختص بإصدار أمر الأداء ليس كما سبق، وإنما القاضي المشرف على مكتب إدارة الدعوى. فالمادة 4-147 تنطوي ضمنا على ما يفيد اختصاص القاضي المشرف بإصدار أوامر الأداء."},{"kind":"text","text":"81- واستكمالا للبحث في مسألة تحديد قاضي الأداء المختص، تجدر الإشارة إلى أن الذهن لم ينصرف إلى قاضي الأمور المستعجلة ولا إلى قاضي التنفيذ. فعدم اختصاص قاضي الأمور المستعجلة راجع إلى أن اختصاصه ينحصر في الأمور المستعجلة، بينما المطالبة محل أمر الأداء ليست من هذه الأمور. وعدم اختصاص قاضي التنفيذ راجع إلى أن اختصاصه يبدأ بعد وجود السند التنفيذي، بينما إصدار أمر الأداء يكون قبلا."},{"kind":"text","text":"وكل ذلك يملك المشرع الاتحادي أو المحلي أن يخرج عليه بنص خاص. وقد خرجت بعض جهات القضاء المحلي على هذا الوضع بالفعل. فالقواعد المنظمة لدائرة القضاء أبو ظبي مثلا أسندت إلى قاضي الأمور المستعجلة الاختصاص بإصدار أوامر الأداء."},{"kind":"text","text":"الفرع الرابع: إجراءات طلب أمر الأداء"},{"kind":"text","text":"82- الأصل أن على الدائن الذي تتوافر في مطالبته شروط استصدار أمر أداء، أن يتبع الإجراءات الواردة بخصوص هذه الأوامر، وليس تلك التي تتبع في رفع الدعاوى (مادة1- 143)."},{"kind":"text","text":"هذه الإجراءات تسير على النحو الآتي:"},{"kind":"text","text":"(أ) تبدأ إجراءات استصدار أمر الأداء بإجراء يجب اتخاذه أولا قبل الاتصال بالقضاء. هذا الإجراء يتمثل في تكليف المدين بالوفاء، في ميعاد خمسة أيام على الأقل، وبأي وسيلة من وسائل الإعلان المحددة في القانون (مادة 1-144)."},{"kind":"text","text":"(ب) أما الإجراء التالي فهو تقديم عريضة- ورقية أو الكترونية بحسب الأحوال- إلى مكتب إدارة الدعوى (مادة 2- 144). هذه العريضة يجب أن تشتمل على بيانات صحيفة الدعوى، كما يجب أن يرفق بها سند الدين وما يثبت حصول التكليف بالوفاء (مادة 2- 144و3). ولأنه يجب تكليف المدين بالوفاء خلال خمسة أيام، فإنه يجب على الدائن ألا يتقدم بالعريضة إلا بعد انقضاء هذه المدة، والتي تبدأ من اليوم التالي لإعلان المدين بالتكليف."},{"kind":"text","text":"(ج) وتجب ملاحظة أن المواجهة مستبعدة في هذه المرحلة. إذ على مكتب إدارة الدعوى أن يحيل العريضة إلى قاضي الأداء المختص دون إعلانها إلى المدين."},{"kind":"text","text":"(د) وأخيرا تعتبر عريضة أمر الأداء منتجة لكافة الآثار التي تترتب على أي مطالبة قضائية أخرى، كالمطالبة من خلال صحيفة الدعوى، ولو كانت المحكمة المقدم إليها العريضة غير مختصة (مادة 5-144). ولا شك أن من أهم هذه الآثار قطع التقادم."},{"kind":"text","text":"الفرع الخامس: الأمر الصادر في طلب الأداء"},{"kind":"text","text":"83- يفصل قاضي الأداء في الطلب بقرار قضائي ملزم يغلق معه الخصومة الخاصة- إن جاز التعبير- التي نشأت بمجرد تقديم عريضة الأداء. هذا القرار أقرب إلى الحكم القضائي. ولذلك فإنه إذا كان صادرا في الموضوع، فإنه يحوز حجية الأمر المقضي (المادة 87 إثبات)."},{"kind":"text","text":"وهو يصدر في غير جلسة، وبالتالي دون حضور الطالب أو المدين أو حتى الكاتب. والنص على أنه يصدر خلال ثلاثة أيام على الأكثر من تقديم العريضة (مادة 4- 144). هذا الميعاد لا يتعلق بالخصوم وإنما بالقاضي، ولذلك فهو يعتبر ميعادا تنظيميا، ولن يترتب بالتالي أي بطلان على مخالفته."},{"kind":"text","text":"ويطلق على هذا القرار القضائي مسمى قانوني خاص به هو أمر الأداء. وهذا المسمى ينطبق أيا كان مضمون هذا الأمر، أي سواء كان صادرا بعدم قبول الطلب، أو صادرا بالأداء، أو برفضه. من اللازم إذا تناول هذه الصور الثلاثة المختلفة التي يظهر بها أمر الأداء."},{"kind":"text","text":"84- (أ) فالصورة الأولي، هي أن يصدر أمر الأداء بعدم قبول الطلب. ينطبق ذلك بطبيعة الحال على أمر الأداء الذي يقرر عدم القبول بعبارة صريحة. كما ينطبق ذلك أيضا على أمر الأداء الذي يقرر عدم النظر في الطلب ولو لسبب آخر غير عدم القبول بالمعنى الدقيق."},{"kind":"text","text":"والأمر الصادر بعدم القبول بأي معنى مما سبق يجب أن يكون مسببا (مادة 145). هذا التسبيب يستند في معظم الأحوال إلى تخلف أحد أسباب القبول الخاصة بأوامر الأداء، وأهمها عدم توافر شرط أو أكثر من الشروط المطلوبة في الحق محل المطالبة. إذ كان يجب على الطالب في هذه الحالة رفع الدعوى العادية وليس سلوك طريق أمر الأداء."},{"kind":"text","text":"أيضا يمكن تسبيب الأمر الصادر بعدم القبول تأسيسا على تخلف أحد الأسباب العامة لقبول الطلب الذي يوجه إلى القضاء أيا كان الإجراء الذي يقدم به. كأن يكون الحق المطالب به غير مشروع، أو يكون طالب الأمر أو خصمه ليس بذي صفة."},{"kind":"text","text":"وقد يؤسس الأمر الصادر بعدم القبول على تخلف الشروط الإجرائية، مثل تقديم عريضة استصدار أمر الأداء دون إرفاق سند الدين أو ما يثبت حصول التكليف بالوفاء، أو لأن الحق الوارد في التكليف أقل من المطلوب في العريضة، أو لأن العريضة تقدمت قبل انقضاء الخمسة أيام المقررة قانونا، أو لأنها لم تشتمل على بيانات صحيفة الدعوى. أيضا يمكن تسبيب عدم القبول على سند من أن الطلب مقدم إلى قاض غير مختص."},{"kind":"text","text":"85- (ب) أما الصورة الثانية، فهي أن يصدر أمر بالأداء بالفعل، بمعنى أن القاضي يستجيب للمطالبة. وليس بالضرورة أن يستجيب قاضي الأداء لكل عناصر المطالبة. فقد تتوافر الشروط المطلوبة في شق من المطالبة وليس جميعها، كأن تتوافر في الحق الأصلي ولا تتوافر في الفوائد أو التعويضات المطلوبة إلى جانبه، وعندئذ لا مانع من صدور الأمر بأداء جزئي. ويجب في جميع الأحوال أن يبين في الأمر المبلغ أو المنقول الواجب أداؤه."},{"kind":"text","text":"هذا، ولم يتطلب المشرع في الأمر الصادر بالأداء أن يكون مسببا."},{"kind":"text","text":"86- (ج) أما الصورة الثالثة والأخيرة، فهي أن يصدر الأمر بالرفض. والرفض كما الاستجابة للطلب، قد يكون كليا أو جزئيا. ويجب أن يكون أمر الرفض مسببا (مادة 145). ولا نعتقد من جانبنا وجود سبب للرفض مستقل عن عدم القبول. فتخلف شرط أو أكثر من الشروط المطلوبة لإصدار أمر بالأداء يستوجب عدم القبول وليس الرفض. العلة في ذلك أن الأمر بالرفض يحوز حجية الأمر المقضي ويمنع تجديد المطالبة ولو من خلال الدعوى، بينما عدم القبول لا يمنع من ذلك. ولا يجوز حرمان الدائن من هذا التجديد لمجرد عدم ثبوت الدين بالكتابة مثلا أو لعدم تعيين المقدار أو لكون المطلوب عقارا وليس نقودا أو منقولا."},{"kind":"text","text":"وبناء عليه، نوصي بألا يصدر أمر أداء متضمنا عبارة الرفض."},{"kind":"heading","text":"87- إعلان الأمر بالأداء"},{"kind":"text","text":"بعدما يتسلم الدائن نسخة من أمر الأداء، فعليه أن يطلب إعلان المدين بالأمر الصادر ضده بالأداء، وفقا لقواعد الإعلان المقررة في القانون (مادة 146- 1). وبناء عليه يصح الإعلان بالتسليم باليد لشخص المدين أو في موطنه، كما يصح إعلانه بوسائل التقنية الحديثة، وكذلك إعلانه بالنشر أو الإدراج على الموقع الالكتروني للمحكمة عند تعذر وسائل الإعلان الأخرى."},{"kind":"text","text":"وعلى جانب آخر، يجب إعلان الأمر الصادر بالأداء إلى المدين خلال ثلاثة أشهر من تاريخ صدوره، وإلا اعتبر كأن لم يكن (مادة 2- 146). فإذا اعتبر كذلك، جاز استصدار أمر جديد بإجراءات جديدة بما في ذلك التكليف بالوفاء. مع الأخذ في الاعتبار أن انقطاع التقادم الذي حدث عند تقديم طلب الأداء الأول، سيعتبر هو الآخر كأن لم يكن."},{"kind":"text","text":"على أن المقصود في كل ما سبق هو الأمر الصادر بالأداء بمعنى الكلمة. أما الأمر الصادر بعدم القبول- أو بالرفض- فهو لا يحتاج إلى إعلان نظرا لعدم وجود مصلحة للمدين في العلم به. على أنه إذا أراد الدائن طلب مراجعة مثل هذا القرار، فإنه سيكون مضطرا إلى إعلانه للمدين من خلال صحيفة التظلم أو الاستئناف."},{"kind":"text","text":"الفرع السادس: طرق مراجعة الأمر"},{"kind":"text","text":"88- كان ماثلا في ذهن المشرع الطبيعة الخاصة لأمر الأداء، فهو من ناحية المضمون يقترب من الحكم القضائي بينما هو من ناحية الشكل أقرب إلى العمل الولائي. ولذلك أخضع المشرع أوامر الأداء لطريقين من طريق المراجعة، أحدهما هو المخصص عادة للحكم القضائي وهو الطعن بالاستئناف، والآخر هو طريق المراجعة المخصص عادة للأعمال الولائية وهو التظلم. ولكن ليس معنى ذلك أن يخضع الأمر الواحد لكلا الطريقين في آن أو حتى على سبيل التتابع. فالحاصل أن المشرع قام بتوزيع أوامر الأداء على كلا الطريقين، بحيث تخضع طائفة منها لطريق التظلم دون غيره، بينما تخضع الطائفة الأخرى للاستئناف."},{"kind":"text","text":"فإذا تحدد طريق المراجعة المقرر، فإنه يستوي بعد ذلك أن يكون الأمر صادرا بالأداء أو برفضه أو بعدم القبول. على أنه يجب بطبيعة الحال أن يطلب المراجعة صاحب المصلحة فيها. فلا يجوز التظلم أو الاستئناف إلا من الدائن الذي صدر الأمر بعدم قبول طلبه أو برفضه كليا أو جزئيا، أو من المدين الذي صدر عليه الأمر بالأداء. ولا شك أن مخالفة طريق المراجعة الواجب اتخاذه، أو سلوكه ممن ليست له المصلحة بأوصافها المختلفة أو بعد الميعاد المقرر، سوف يؤدي حتما إلى الحكم بعدم القبول."},{"kind":"text","text":"سوف نتناول أولا طريق التظلم، ثم نتناول بعد ذلك طريق الاستئناف."},{"kind":"text","text":"أولا: التظلم"},{"kind":"heading","text":"89- (أ) أمر الأداء القابل للتظلم"},{"kind":"text","text":"\"للخصوم التظلم من أمر الأداء إذا كانت قيمته في حدود النصاب الانتهائي لمحكمة أول درجة.. \"(مادة 1- 147). يستفاد من هذا النص أن التظلم قاصر على أمر الأداء الذي يصدر في مطالبة لا تتجاوز خمسين ألف درهم،، فهذا هو النصاب الانتهائي لمحكمة أول درجة."},{"kind":"heading","text":"90- (ب) ميعاد التظلم"},{"kind":"text","text":"\"للخصوم التظلم من أمر الأداء.. خلال (15) خمسة عشر يوما من تاريخ إعلان المدين بالأمر، ومن تاريخ صدور القرار بالنسبة للدائن..\" (مادة 1- 147). وتطبيقا للقواعد العامة، يترتب على عدم تقديم التظلم خلال الميعاد سقوط الحق في التظلم."},{"kind":"text","text":"ولا يجب أن يثور في الذهن أنه عند سقوط الحق في التظلم، أن أمر الأداء يصير قابلا للاستئناف. فالواقع أن الاستئناف مخصص للطائفة الأخرى من أوامر الأداء، وهي تلك التي لم تكن قابلة للتظلم من الأصل، وهذا ما سوف يتأكد لنا حالا."},{"kind":"text","text":"ولذلك يجب التأكيد على أن سقوط الحق في التظلم يجعل أمر الأداء نهائيا."},{"kind":"heading","text":"91- (ج) الاختصاص بالتظلم"},{"kind":"text","text":"ينعقد الاختصاص بنظر التظلم لقاضي أمر الأداء المختص (مادة 1- 147). وهو دائما قاض فرد. ولكن ليس بالضرورة أن يكون القاضي الذي ينظر التظلم هو نفسه الذي أصدر الأمر. المهم أن يكون قاضي إحدى دوائر المحكمة الابتدائية التي أصدرت الأمر."},{"kind":"heading","text":"92- (د) خصومة التظلم"},{"kind":"text","text":"ينشأ عن التظلم خصومة قضائية، وذلك لأنه يكون بالإجراءات المعتادة لرفع الدعوى، وتراعى عند نظره القواعد والإجراءات المتبعة أمام المحكمة (مادة 147 -1) الابتدائية. لذلك سيشغل المتظلم مركز المدعي ويكون الخصم الآخر في مركز المدعى عليه."},{"kind":"text","text":"فإذا كان التظلم مرفوعا من الدائن، فإنه سيطلب إلغاء الأمر الصادر بعدم القبول أو بالرفض وإصدار حكم بما سبق أن طلبه في عريضة أمر الأداء. ولا مانع من أن يضيف طلبات أخرى مرتبطة بطلبه هذا. فله أن يطلب مثلا بباقي المديونية المستحقة، ولو كانت مما لا يجب استيفاؤها بطريق أمر الأداء. ذلك أن المشرع لم يشترط سلوك هذا الطريق إلا بالنسبة لما يطالب به الدائن ابتداء."},{"kind":"text","text":"أما إذا كان التظلم مرفوعا من المدين، فإنه أيضا سيطلب إلغاء الأمر الصادر ضده بالأداء ورفض الطلب الذي كان مقدما في عريضة الأداء، ولا مانع من أن يضيف هو أيضا طلبا آخر مرتبطا أو يطلب إدخال ضامن."},{"kind":"text","text":"وأيا كان المتظلم وأيا كان الطلب المبدى، فإنه يجوز إبدائه سواء في ذات صحيفة التظلم أو أثناء سير الخصومة. وأخيرا، للخصم بحسب الأحوال أن يقدم ما لديه من وسائل دفاع."},{"kind":"heading","text":"93- (ه) الحكم في التظلم"},{"kind":"text","text":"يصدر في خصومة التظلم حكم قضائي تودع أسبابه في ذات الجلسة، يفصل في التظلم وينهي بالتالي الخصومة (مادة 1-147)."},{"kind":"text","text":"وقد قرر المشرع أن يكون هذا الحكم نهائيا غير قابل للطعن (مادة 1- 147). معنى ذلك أنه لن يكون قابلا للاستئناف ولا حتى لالتماس إعادة النظر. ومنع الطعن بالاستئناف يبدو منطقيا، بل لم تكن هناك حاجة إلى ذكره، نظرا لأن الحكم نهائي بنص القانون. وحتى إذا لم يوجد هذا النص فالحكم أيضا نهائي، إذ المطالبة التي صدر فيها الأمر وكانت بدورها محلا لخصومة التظلم هي في الأساس داخلة في النصاب الانتهائي لمحكمة أول درجة. بينما لا يوجد مبرر لمنع الطعن بالالتماس، إلا أننا لا نملك سوى الانصياع لحكم النص."},{"kind":"text","text":"ثانيا: الاستئناف"},{"kind":"heading","text":"94- (أ) أمر الأداء القابل للاستئناف"},{"kind":"text","text":"\".. يجوز استئناف أمر الأداء الذي تتجاوز قيمته النصاب الانتهائي لمحكمة أول درجة..\"(مادة 2- 147). يستفاد من هذا النص أن جميع أوامر الأداء الصادرة في المطالبات التي تزيد على خمسين ألف درهم- وتدخل بالتالي في النصاب الابتدائي- تكون قابلة للطعن بالاستئناف. لن يخرج من مجال الاستئناف إذا سوى طائفة محددة من أوامر الأداء- سبقت الإشارة إليها- وهي تلك التي تقبل التظلم. فالطعن بالاستئناف في أمر الأداء هو إذا القاعدة بينما التظلم هو الاستثناء."},{"kind":"heading","text":"95- (ب) ميعاد الاستئناف"},{"kind":"text","text":"لم يعد ينص المشرع على ميعاد خاص لاستئناف أمر الأداء. ولذلك فإن ميعاده هو الميعاد المقرر أصلا لاستئناف الأحكام، أي ثلاثون يوما. وطبقا للقواعد العامة، سيبدأ هذا الميعاد من تاريخ صدور الأمر- أو بمعنى أدق من اليوم التالي لصدوره- إذا كان المستأنف هو الدائن، بينما سيبدأ من اليوم التالي لتاريخ إعلان الأمر إذا كان المستأنف هو المدين. ويترتب على عدم مراعاة الميعاد سقوط الحق في الطعن، وتقضي به المحكمة من تلقاء نفسها."},{"kind":"heading","text":"96- (ج)خصومة الاستئناف"},{"kind":"text","text":"لا تثور مشكلة بخصوص المحكمة المختصة بنظر الاستئناف. فعند غياب النص سيكون من الطبيعي أن ينصرف الذهن إلى محكمة الاستئناف التي تتبعها المحكمة الابتدائية الصادر عن أحد قضاتها أمر الأداء المطعون عليه."},{"kind":"text","text":"ولا مشكلة أيضا في كيفية رفع الاستئناف وإعلانه، فإجراءات خصومة استئناف أمر الأداء تخضع من حيث المبدأ للإجراءات المقررة لاستئناف الأحكام (مادة 147 -2). على أن ذلك لا يمنع من وجود بعض أوجه الخصوصية، والتي تبدأ في الظهور مبكرا وعقب انعقاد الخصومة بتمام إعلان صحيفة الاستئناف."},{"kind":"text","text":"فأول خصوصية هي أنه سوف يتم نظر الاستئناف على وجه السرعة. فقد تقرر أن يتم الفصل فيه خلال أسبوع من إتمام إعلان صحيفة الاستئناف، ودون المرور بمرحلة التحضير من مكتب إدارة الدعوى والقاضي المشرف (مادة 3- 147). وقد تفرع عن ذلك نتيجتان: الأولي أنه يجب أن تشتمل صحيفة الاستئناف عند قيدها على أسباب الاستئناف، وإلا وجب الحكم بعدم قبول الاستئناف (مادة 2- 147). أما النتيجة الثانية- وغير المنصوص عليها- فهي أن على المستأنف عليه أن يسرع في تقديم مذكرة بدفاعه، نظرا لأن جلسة الفصل في الاستئناف لن تتجاوز الأسبوع."},{"kind":"text","text":"وثاني أوجه الخصوصية، فهو أنه لا توجد من حيث المبدأ جلسة مرافعة. فالأصل أن المحكمة تفصل في استئناف أمر الأداء في غرفة المشورة (مادة 147 - 2 من القانون). هذا مع مراعاة أنه إذا اقتضى الأمر غير ذلك، فإن للمحكمة تحديد جلسة مرافعة لنظر الموضوع (مادة 2- 147 من القانون). ولعل أبرز سبب قد يدعو محكمة الاستئناف إلى نظام الجلسة أو الجلسات، هو ألا يكون المستأنف عليه قد قدم مذكرة بدفاعه."},{"kind":"text","text":"وثالث أوجه الخصوصية، فهو أن على محكمة الاستئناف إعادة الدعوى إلى محكمة أول درجة في فرض محدد، رغم استنفاد هذه الأخيرة لولايتها. يقصد بذلك، الفرض الذي تكون فيه المطالبة قد رفعت ابتداء بالطريقة المعتادة لرفع الدعوى، إلا أن \"القاضي المشرف\" قد أعاد تكييفها واعتبرها مطالبة تتوافر فيها شروط استصدار أمر الأداء، وقام بالفعل بإصدار أمر بالأداء فيها، ثم رأت محكمة الاستئناف إلغاء الأمر لعدم توافر شروط استصداره. فمسايرة القواعد العامة التي تحكم الطعن بالاستئناف، تقتضي أن تقوم محكمة الاستئناف ذاتها بإصدار حكم جديد في هذه المطالبة، نظرا لأنه سبق الفصل في موضوعها من قاض في مستوى محكمة الدرجة الأولى وهو القاضي المشرف، أي أن قضاء أول درجة- وأيا كان هذا القضاء- قد استنفد ولايته ولا تجوز إعادة الدعوى إليه. ومع ذلك كان للمشرع توجه مخالف. فقد قررت المادة 4-147 أن على محكمة الاستئناف في الفرض محل البحث أن تعيد الدعوى إلى محكمة أول درجة لنظرها وفقا للطريق المعتاد لنظر الدعاوى. الحكمة من هذا الاستثناء، أن الأصل هو سلوك طريق الدعوى وليس أمر الأداء، فإذا تجاوب الخصوم مع هذا الأصل، إلا أن القاضي المشرف قد حال بينهم وبين قاضيهم الطبيعي دون وجه حق، كان من الواجب على محكمة الاستئناف أن تعيد الأمور إلى أصلها."},{"kind":"text","text":"ورابع أوجه الخصوصية، فهو أن على محكمة الاستئناف ألا تعيد المطالبة إلى محكمة أول درجة في باقي الفروض، ولو لم تكن هذه الأخيرة قد استنفدت ولايتها. تظهر قيمة هذه الخصوصية في الفرض الذي يكون فيه محل الطعن \"أمر أداء صادر بعدم القبول\"، وانتهت محكمة الاستئناف إلى إلغائه. ففي هذا الفرض يتوجب على القضاء الفصل في الموضوع. ولكن أي قضاء بالتحديد؟ طبقا للقواعد العامة، كان يتوجب على محكمة الاستئناف إعادة المطالبة إلى محكمة أول درجة لعدم استنفادها لولايتها تجاه الموضوع. إلا أن المادة 3- 147 منعت محكمة الاستئناف من إعادة الدعوى إلى محكمة الدرجة الأولى في عبارة عامة تنطبق على مختلف الفروض ومنها بطبيعة الحال الفرض محل البحث. وبناء عليه يجب على محكمة الاستئناف- ورغم أنها محكمة للدرجة الثانية- الفصل في موضوع مطالبة لم يسبق الفصل فيه من قضاء أول درجة، وهذا هو وجه الخصوصية في هذا الفرض."},{"kind":"text","text":"أما في باقي الفروض التي نقابلها عند الطعن بالاستئناف في أمر الأداء، فإن عدم إعادة الدعوى إلى محكمة أول درجة، سيكون متسقا مع القواعد العامة وخاليا من الخصوصية."},{"kind":"heading","text":"97- (د) الطعن في الحكم الصادر في الاستئناف"}]);
